screenPanels.initJs:
function(container, apiUrl, tables) {
  // タブ切り替え機能
  const tabButtons = container.querySelectorAll('.tab-btn');
  const tabContents = container.querySelectorAll('.tab-content');

  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const tabName = btn.dataset.tab;

      // すべてのタブボタンを非アクティブに
      tabButtons.forEach(b => {
        b.style.borderBottom = 'none';
        b.style.color = 'var(--text-muted)';
      });

      // すべてのタブコンテンツを非表示に
      tabContents.forEach(content => {
        content.style.display = 'none';
      });

      // クリックされたタブをアクティブに
      btn.style.borderBottom = '2px solid var(--primary)';
      btn.style.color = 'var(--text)';
      container.querySelector(`#tab-${tabName}`).style.display = 'block';
    });
  });

  // 保存ボタン
  container.querySelector('[data-testid="save-button"]').addEventListener('click', async () => {
    const quantity = container.querySelector('[data-testid="quantity-input"]').value;
    const amount = container.querySelector('[data-testid="amount-input"]').value;
    const address = container.querySelector('[data-testid="address-input"]').value;
    const reason = container.querySelector('[data-testid="reason-select"]').value;
    const notes = container.querySelector('[data-testid="notes-textarea"]').value;

    if (!reason) {
      alert('修正理由を選択してください');
      return;
    }

    if (!notes.trim()) {
      alert('修正備考を入力してください');
      return;
    }

    // 修正履歴を保存（テーブルインデックスは修正履歴テーブルを想定）
    const correctionData = {
      修正項目名: '数量・金額・住所',
      修正前値: JSON.stringify({ quantity: 3, amount: 30000, address: '東京都渋谷区道玄坂1-2-3' }),
      修正後値: JSON.stringify({ quantity, amount, address }),
      修正理由: reason,
      修正備考: notes,
      修正ユーザーID: 'user-001',
      修正日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, correctionData); // テーブルインデックス 1 = 修正履歴
    if (saved) {
      alert('修正内容を保存しました');
      // 修正履歴タブを表示
      container.querySelector('[data-tab="history"]').click();
    }
  });

  // キャンセルボタン
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    if (confirm('修正を破棄してもよろしいですか？')) {
      window.showScreen('scr-1781413262699'); // 受注データ検証ダッシュボードに戻る
    }
  });

  // 修正を承認ボタン
  container.querySelector('[data-testid="approve-button"]').addEventListener('click', async () => {
    if (confirm('この修正を承認しますか？')) {
      // 承認フロー更新（テーブルインデックス 2 = 連携承認フロー）
      const approvalData = {
        現在ステータス: '承認済',
        承認判定: '承認',
        承認コメント: '修正内容を確認し承認します',
        承認日時: new Date().toISOString()
      };

      const approved = await window.aivicApi.update(2, 'flow-001', approvalData);
      if (approved) {
        alert('修正を承認しました');
        window.showScreen('scr-1781413262699');
      }
    }
  });

  // 却下ボタン
  container.querySelector('[data-testid="reject-button"]').addEventListener('click', () => {
    const reason = prompt('却下理由を入力してください:');
    if (reason) {
      alert(`修正を却下しました: ${reason}`);
      window.showScreen('scr-1781413262699');
    }
  });

  // 再検証ボタン
  container.querySelector('[data-testid="revalidate-button"]').addEventListener('click', async () => {
    alert('修正内容を再検証中...');
    // 実際には検証処理を呼び出す
    setTimeout(() => {
      alert('再検証完了。新しい検証結果を表示します');
      // 検証結果タブを表示
      container.querySelector('[data-tab="validation"]').click();
    }, 1500);
  });

  // 戻るボタン
  container.querySelector('[data-testid="back-button"]').addEventListener('click', () => {
    window.showScreen('scr-1781413262699');
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const tableIndex = 0; // 重複受注検出結果テーブル

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#duplicate-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); color: var(--text-muted);"><td colspan="6" style="padding: 20px; text-align: center; font-size: 12px;">該当する重複受注がありません</td></tr>';
      container.querySelector('[data-testid="result-count"]').textContent = '0';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const scoreClass = row.マッチング信頼度 >= 90 ? 'high' : row.マッチング信頼度 >= 80 ? 'medium' : 'low';
      const statusBg = row.検出ステータス === '統合済み' ? 'rgba(100,200,100,0.15)' : 
                       row.検出ステータス === '誤検出' ? 'rgba(200,100,100,0.15)' : 'transparent';
      return `
        <tr data-id="${row.重複受注検出結果ID}" style="border-bottom: 1px solid var(--border); cursor: pointer; background: ${statusBg}; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,215,0,0.08)'" onmouseout="this.style.background='${statusBg}'">
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text); font-weight: 500;">${row.主受注ID ? row.主受注ID.substring(0, 8) : '-'}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${row.顧客名 || '-'}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text-muted); font-size: 11px;">${row.チャネル名 || '-'}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); text-align: right; color: var(--text);">¥${row.金額 ? row.金額.toLocaleString() : '0'}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); text-align: center; font-weight: 600; color: ${scoreClass === 'high' ? '#ffd700' : scoreClass === 'medium' ? '#ffb347' : '#ff6a6a'};">${row.マッチング信頼度 || 0}%</td>
          <td style="padding: 8px; text-align: center; font-size: 11px; color: var(--text-muted);">${row.検出ステータス || '未確認'}</td>
        </tr>
      `;
    }).join('');

    container.querySelector('[data-testid="result-count"]').textContent = rows.length;
  }

  // 2. 初期データ描画
  renderRows(tables[0]?.records || []);

  // 3. 検索ボタン
  container.querySelector('[data-testid="search-button"]').addEventListener('click', async () => {
    const keyword = container.querySelector('[data-testid="search-keyword"]').value.toLowerCase();
    const scoreFilter = container.querySelector('[data-testid="score-filter"]').value;
    const statusFilter = container.querySelector('[data-testid="status-filter"]').value;

    const allRows = await window.aivicApi.list(tableIndex) || tables[0]?.records || [];

    const filtered = allRows.filter(row => {
      const matchKeyword = !keyword || 
        (row.主受注ID && row.主受注ID.toLowerCase().includes(keyword)) ||
        (row.顧客名 && row.顧客名.toLowerCase().includes(keyword));

      const matchScore = !scoreFilter || 
        (scoreFilter === '90-100' && row.マッチング信頼度 >= 90) ||
        (scoreFilter === '80-89' && row.マッチング信頼度 >= 80 && row.マッチング信頼度 < 90) ||
        (scoreFilter === '70-79' && row.マッチング信頼度 >= 70 && row.マッチング信頼度 < 80) ||
        (scoreFilter === '0-69' && row.マッチング信頼度 < 70);

      const matchStatus = !statusFilter || row.検出ステータス === statusFilter;

      return matchKeyword && matchScore && matchStatus;
    });

    renderRows(filtered);
  });

  // 4. 行クリックで比較パネル表示
  container.querySelector('#duplicate-tbody').addEventListener('click', (e) => {
    const row = e.target.closest('tr');
    if (!row) return;

    const rowId = row.dataset.id;
    const allRows = tables[0]?.records || [];
    const selectedRow = allRows.find(r => r.重複受注検出結果ID === rowId);

    if (!selectedRow) return;

    // 比較パネルを表示
    container.querySelector('#compare-empty').style.display = 'none';
    container.querySelector('#compare-detail').style.display = 'block';

    // ペア情報
    container.querySelector('[data-testid="compare-pair-info"]').textContent = 
      `${selectedRow.主受注ID?.substring(0, 8) || '-'} ↔ ${selectedRow.副受注ID?.substring(0, 8) || '-'}`;

    // 主受注情報
    const mainContent = `
      <div><strong>受注ID:</strong> ${selectedRow.主受注ID?.substring(0, 12) || '-'}</div>
      <div><strong>顧客名:</strong> ${selectedRow.顧客名 || '-'}</div>
      <div><strong>受注日時:</strong> ${selectedRow.受注日時 || '-'}</div>
      <div><strong>チャネル:</strong> ${selectedRow.チャネル名 || '-'}</div>
      <div><strong>金額:</strong> ¥${selectedRow.金額 ? selectedRow.金額.toLocaleString() : '0'}</div>
    `;
    container.querySelector('#compare-main-content').innerHTML = mainContent;

    // 副受注情報（簡略版 - 実際にはDB から取得）
    const subContent = `
      <div><strong>受注ID:</strong> ${selectedRow.副受注ID?.substring(0, 12) || '-'}</div>
      <div><strong>顧客名:</strong> ${selectedRow.顧客名 || '-'}</div>
      <div><strong>受注日時:</strong> ${selectedRow.受注日時 || '-'}</div>
      <div><strong>チャネル:</strong> ${selectedRow.チャネル名 || '-'}</div>
      <div><strong>金額:</strong> ¥${selectedRow.金額 ? selectedRow.金額.toLocaleString() : '0'}</div>
    `;
    container.querySelector('#compare-sub-content').innerHTML = subContent;

    // 差分項目
    const diffList = `
      <div style="padding: 6px; background: rgba(255,100,100,0.1); border-radius: 3px; margin-bottom: 4px;">
        <span style="color: #ff6a6a;">●</span> 受注日時が異なる（主: 2024-01-15 10:30 / 副: 2024-01-15 10:32）
      </div>
      <div style="padding: 6px; background: rgba(255,100,100,0.1); border-radius: 3px;">
        <span style="color: #ff6a6a;">●</span> 金額が異なる（主: ¥50,000 / 副: ¥50,500）
      </div>
    `;
    container.querySelector('#compare-diff-list').innerHTML = diffList;

    // マッチング情報
    container.querySelector('#compare-confidence').textContent = `${selectedRow.マッチング信頼度 || 0}%`;
    container.querySelector('#compare-rule').textContent = selectedRow.検出ルールID || '-';
    container.querySelector('#compare-reason').textContent = selectedRow.マッチング理由 || '顧客名・電話番号が一致';
  });

  // 5. 確認・保存ボタン
  container.querySelector('[data-testid="confirm-button"]').addEventListener('click', async () => {
    const decision = container.querySelector('[data-testid="decision-select"]').value;
    const reviewer = container.querySelector('[data-testid="reviewer-input"]').value;
    const remark = container.querySelector('[data-testid="remark-textarea"]').value;

    if (!decision) {
      alert('対応方針を選択してください');
      return;
    }

    const selectedRow = container.querySelector('#duplicate-tbody tr[data-id]');
    if (!selectedRow) {
      alert('ペアを選択してください');
      return;
    }

    const rowId = selectedRow.dataset.id;
    const updateData = {
      検出ステータス: decision === '統合' ? '統合済み' : decision === '分離' ? '確認済み' : decision === '誤検出' ? '誤検出' : '保留',
      確認者ID: reviewer,
      確認日時: new Date().toISOString(),
      備考: remark
    };

    const result = await window.aivicApi.update(tableIndex, rowId, updateData);
    if (result) {
      alert('対応方針を保存しました');
      // 再検索
      container.querySelector('[data-testid="search-button"]').click();
    }
  });

  // 6. 詳細確認画面へのリンク
  container.querySelector('[data-testid="compare-detail-link"]').addEventListener('click', () => {
    window.showScreen('scr-1781413282852'); // 受注データ詳細確認・修正画面
  });

  // 7. CSV出力
  container.querySelector('[data-testid="export-csv-button"]').addEventListener('click', async () => {
    const allRows = await window.aivicApi.list(tableIndex) || tables[0]?.records || [];
    if (allRows.length === 0) {
      alert('出力するデータがありません');
      return;
    }

    const headers = ['重複受注検出結果ID', '主受注ID', '副受注ID', '顧客名', 'チャネル名', '金額', 'マッチング信頼度', '検出ステータス', 'マッチング理由'];
    const csv = [
      '\uFEFF' + headers.join(','),
      ...allRows.map(row => [
        row.重複受注検出結果ID || '',
        row.主受注ID || '',
        row.副受注ID || '',
        row.顧客名 || '',
        row.チャネル名 || '',
        row.金額 || '',
        row.マッチング信頼度 || '',
        row.検出ステータス || '',
        row.マッチング理由 || ''
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `重複受注検出_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  const tableIndex = 0; // チャネル間矛盾検出結果テーブル
  let allRows = [];
  let selectedRows = new Set();
  let currentTab = 'all';

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#discrepancy-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted);">矛盾検出結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const severity = r.重要度 || r.重要度レベル || '中';
      const severityColor = severity === '高' ? '#ff6b00' : severity === '低' ? '#4a9eff' : '#ffc107';
      const discrepancyType = r.矛盾タイプ || '不明';
      const score = r.信頼度スコア || 0;
      const priority = r.優先度 || 3;

      return `<tr data-id="${r.矛盾検出結果ID || r.id}" style="background: var(--bg-main); border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background='var(--bg-main)'">
        <td style="padding: 8px; text-align: center;"><input type="checkbox" class="row-check" data-id="${r.矛盾検出結果ID || r.id}" style="accent-color: var(--primary);"></td>
        <td style="padding: 8px; color: var(--text); font-weight: 500;">${r.受注ID_1 ? r.受注ID_1.substring(0, 8) : '—'}</td>
        <td style="padding: 8px; color: var(--text);"><span style="display: inline-block; padding: 2px 6px; background: rgba(255,107,0,0.2); color: #ff6b00; border-radius: 3px; font-size: 11px;">${discrepancyType}</span></td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${score}%</td>
        <td style="padding: 8px; text-align: center;"><span style="display: inline-block; padding: 2px 6px; background: ${severityColor}22; color: ${severityColor}; border-radius: 3px; font-size: 11px; font-weight: 500;">P${priority}</span></td>
      </tr>`;
    }).join('');

    // 行クリックで詳細表示
    tbody.querySelectorAll('tr').forEach(tr => {
      tr.addEventListener('click', (e) => {
        if (e.target.closest('.row-check')) return;
        const id = tr.dataset.id;
        const row = rows.find(r => (r.矛盾検出結果ID || r.id) === id);
        if (row) showDetail(row);
      });
    });
  }

  // 2. 詳細表示
  function showDetail(row) {
    const compPanel = container.querySelector('#comparison-panel');
    const scorePanel = container.querySelector('#score-panel');
    const correctionForm = container.querySelector('#correction-form');
    const emptyState = container.querySelector('#empty-state');

    // チャネル1データ
    const ch1Data = `
      <div><strong>受注ID:</strong> ${row.受注ID_1 ? row.受注ID_1.substring(0, 12) : '—'}</div>
      <div><strong>チャネル:</strong> ${row.チャネルID_1 || '—'}</div>
      <div><strong>金額:</strong> ${row.金額_1 || '—'}</div>
      <div><strong>数量:</strong> ${row.数量_1 || '—'}</div>
      <div><strong>顧客:</strong> ${row.顧客名_1 || '—'}</div>
    `;

    // チャネル2データ
    const ch2Data = `
      <div><strong>受注ID:</strong> ${row.受注ID_2 ? row.受注ID_2.substring(0, 12) : '—'}</div>
      <div><strong>チャネル:</strong> ${row.チャネルID_2 || '—'}</div>
      <div><strong>金額:</strong> ${row.金額_2 || '—'}</div>
      <div><strong>数量:</strong> ${row.数量_2 || '—'}</div>
      <div><strong>顧客:</strong> ${row.顧客名_2 || '—'}</div>
    `;

    container.querySelector('#channel-1-data').innerHTML = ch1Data;
    container.querySelector('#channel-2-data').innerHTML = ch2Data;
    container.querySelector('#discrepancy-detail').textContent = row.矛盾内容 || '詳細情報なし';
    container.querySelector('#score-value').textContent = (row.信頼度スコア || 0) + '%';
    container.querySelector('#priority-value').textContent = 'P' + (row.優先度 || 3);

    compPanel.style.display = 'block';
    scorePanel.style.display = 'block';
    correctionForm.style.display = 'block';
    emptyState.style.display = 'none';

    // 修正フォームの状態をリセット
    container.querySelector('#select-correction-channel').value = '';
    container.querySelector('#textarea-correction').value = '';
    container.querySelector('#select-correction-channel').dataset.currentId = row.矛盾検出結果ID || row.id;
  }

  // 3. 初期データ読み込み
  async function loadData() {
    const rows = await window.aivicApi.list(tableIndex);
    allRows = rows || tables[tableIndex]?.records || [];
    renderRows(allRows);
  }

  // 4. フィルタリング
  function applyFilters() {
    const orderId = container.querySelector('#input-order-id').value.toLowerCase();
    const channel = container.querySelector('#select-channel').value;
    const severity = container.querySelector('#select-severity').value;

    let filtered = allRows.filter(r => {
      const matchOrder = !orderId || (r.受注ID_1 || '').toLowerCase().includes(orderId) || (r.受注ID_2 || '').toLowerCase().includes(orderId);
      const matchChannel = !channel || r.チャネルID_1 === channel || r.チャネルID_2 === channel;
      const matchSeverity = !severity || r.重要度 === severity;
      const matchTab = currentTab === 'all' || r.矛盾タイプ === currentTab;
      return matchOrder && matchChannel && matchSeverity && matchTab;
    });

    renderRows(filtered);
  }

  // 5. タブ切り替え
  container.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      container.querySelectorAll('.tab-btn').forEach(b => {
        b.style.color = 'var(--text-muted)';
        b.style.borderBottomColor = 'transparent';
      });
      btn.style.color = 'var(--text)';
      btn.style.borderBottomColor = 'var(--primary)';
      currentTab = btn.dataset.tab;
      applyFilters();
    });
  });

  // 6. 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // 7. チェックボックス処理
  container.querySelector('#check-all').addEventListener('change', (e) => {
    container.querySelectorAll('.row-check').forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedRows.add(cb.dataset.id);
      } else {
        selectedRows.delete(cb.dataset.id);
      }
    });
    updateBulkPanel();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('row-check')) {
      if (e.target.checked) {
        selectedRows.add(e.target.dataset.id);
      } else {
        selectedRows.delete(e.target.dataset.id);
      }
      updateBulkPanel();
    }
  });

  function updateBulkPanel() {
    const bulkPanel = container.querySelector('#bulk-action-panel');
    if (selectedRows.size > 0) {
      bulkPanel.style.display = 'block';
    } else {
      bulkPanel.style.display = 'none';
    }
  }

  // 8. 修正保存
  container.querySelector('#btn-save-correction').addEventListener('click', async () => {
    const channel = container.querySelector('#select-correction-channel').value;
    const content = container.querySelector('#textarea-correction').value;
    const currentId = container.querySelector('#select-correction-channel').dataset.currentId;

    if (!channel || !content) {
      alert('修正対象チャネルと修正内容を入力してください');
      return;
    }

    const updateData = {
      ステータス: '確認中',
      対応内容: content,
      対応日時: new Date().toISOString(),
      対応者ID: 'current-user-id'
    };

    const result = await window.aivicApi.update(tableIndex, currentId, updateData);
    if (result) {
      alert('修正内容を保存しました');
      loadData();
      container.querySelector('#correction-form').style.display = 'none';
      container.querySelector('#comparison-panel').style.display = 'none';
      container.querySelector('#score-panel').style.display = 'none';
      container.querySelector('#empty-state').style.display = 'block';
    }
  });

  // 9. キャンセル
  container.querySelector('#btn-cancel-correction').addEventListener('click', () => {
    container.querySelector('#correction-form').style.display = 'none';
    container.querySelector('#comparison-panel').style.display = 'none';
    container.querySelector('#score-panel').style.display = 'none';
    container.querySelector('#empty-state').style.display = 'block';
  });

  // 10. 一括承認
  container.querySelector('#btn-bulk-approve').addEventListener('click', async () => {
    if (selectedRows.size === 0) return;
    for (const id of selectedRows) {
      await window.aivicApi.update(tableIndex, id, { ステータス: '解決済み' });
    }
    selectedRows.clear();
    loadData();
    updateBulkPanel();
    alert('選択した矛盾を一括承認しました');
  });

  // 11. 一括却下
  container.querySelector('#btn-bulk-reject').addEventListener('click', async () => {
    if (selectedRows.size === 0) return;
    for (const id of selectedRows) {
      await window.aivicApi.update(tableIndex, id, { ステータス: '却下' });
    }
    selectedRows.clear();
    loadData();
    updateBulkPanel();
    alert('選択した矛盾を一括却下しました');
  });

  // 12. CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(tableIndex);
    if (!rows || rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['受注ID_1', '受注ID_2', 'チャネルID_1', 'チャネルID_2', '矛盾タイプ', '矛盾内容', '重要度', 'ステータス', '信頼度スコア'];
    const csv = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => headers.map(h => {
        const val = r[h] || '';
        return typeof val === 'string' && val.includes(',') ? `"${val}"` : val;
      }).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'discrepancy_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス（信頼度スコア、AI_OCR読み込み結果、受注データ修正履歴）
  const confidenceScoreTableIdx = tables.findIndex(t => t.tableName === '信頼度スコア') ?? 0;
  const ocrResultTableIdx = tables.findIndex(t => t.tableName === 'AI_OCR読み込み結果') ?? 1;
  const correctionHistoryTableIdx = tables.findIndex(t => t.tableName === '受注データ修正履歴') ?? 2;

  let allRows = [];
  let selectedRow = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#list-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(255,255,255,0.02);"><td colspan="4" style="padding: 1rem; text-align: center; color: var(--text-muted);">該当データなし</td></tr>';
      updateStatistics([]);
      return;
    }

    tbody.innerHTML = rows.map((r, idx) => {
      const scoreVal = r.総合スコア || r.overall_confidence || 0;
      const isWarning = r.警告フラグ || false;
      const warningLevel = r.警告レベル || (scoreVal < 50 ? '高' : scoreVal < 75 ? '中' : '低');
      const bgColor = idx % 2 === 0 ? 'rgba(255,255,255,0.02)' : 'rgba(255,255,255,0.01)';
      const scoreColor = scoreVal < 50 ? '#ff6a35' : scoreVal < 75 ? '#daa520' : '#4caf50';

      return `
        <tr 
          data-id="${r.id || r.信頼度スコアID || ''}" 
          class="row-item"
          style="background: ${bgColor}; cursor: pointer; transition: background 0.2s;"
          onmouseover="this.style.background='rgba(255,255,255,0.06)'"
          onmouseout="this.style.background='${bgColor}'"
        >
          <td style="padding: 0.4rem; border-bottom: 1px solid rgba(255,255,255,0.05); color: var(--text);">${r.受注データID || r.order_id || '--'}</td>
          <td style="padding: 0.4rem; border-bottom: 1px solid rgba(255,255,255,0.05); color: var(--text);">${r.検証項目 || r.extracted_fields || '--'}</td>
          <td style="padding: 0.4rem; border-bottom: 1px solid rgba(255,255,255,0.05); text-align: center; color: ${scoreColor}; font-weight: 600;">${scoreVal}</td>
          <td style="padding: 0.4rem; border-bottom: 1px solid rgba(255,255,255,0.05); text-align: center;">
            ${isWarning ? `<span style="background: rgba(255,107,53,0.2); color: #ff6a35; padding: 0.2rem 0.4rem; border-radius: 2px; font-size: 0.75rem; font-weight: 600;">${warningLevel}</span>` : '<span style="color: var(--text-muted);">-</span>'}
          </td>
        </tr>
      `;
    }).join('');

    updateStatistics(rows);
  }

  // 統計情報更新
  function updateStatistics(rows) {
    if (!rows || rows.length === 0) {
      container.querySelector('#stat-avg-score').textContent = '--';
      container.querySelector('#stat-warning-count').textContent = '--';
      return;
    }

    const scores = rows.map(r => r.総合スコア || r.overall_confidence || 0);
    const avgScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    const warningCount = rows.filter(r => r.警告フラグ || false).length;

    container.querySelector('#stat-avg-score').textContent = avgScore;
    container.querySelector('#stat-warning-count').textContent = warningCount;
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    const rows = await window.aivicApi.list(confidenceScoreTableIdx);
    if (rows) {
      allRows = rows;
      renderRows(allRows);
    }
  }

  // 3. 検索・フィルタ処理
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const orderId = container.querySelector('#search-order-id').value.trim();
    const rangeFilter = container.querySelector('#filter-confidence-range').value;

    let filtered = allRows;

    if (orderId) {
      filtered = filtered.filter(r => 
        (r.受注データID || r.order_id || '').includes(orderId)
      );
    }

    if (rangeFilter) {
      const [min, max] = rangeFilter.split('-').map(Number);
      filtered = filtered.filter(r => {
        const score = r.総合スコア || r.overall_confidence || 0;
        return score >= min && score <= max;
      });
    }

    renderRows(filtered);
  });

  // リセット
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#search-order-id').value = '';
    container.querySelector('#filter-confidence-range').value = '';
    renderRows(allRows);
  });

  // 4. 行選択イベント
  container.addEventListener('click', (e) => {
    const row = e.target.closest('.row-item');
    if (row) {
      selectedRow = allRows.find(r => (r.id || r.信頼度スコアID) === row.dataset.id);
      if (selectedRow) {
        showDetailForm(selectedRow);
      }
    }
  });

  // 詳細フォーム表示
  function showDetailForm(row) {
    const detailEmpty = container.querySelector('#detail-empty');
    const detailContent = container.querySelector('#detail-content');
    const comparisonEmpty = container.querySelector('#comparison-empty');
    const comparisonContent = container.querySelector('#comparison-content');
    const formEmpty = container.querySelector('#form-empty');
    const formContent = container.querySelector('#form-content');

    detailEmpty.style.display = 'none';
    detailContent.style.display = 'block';
    comparisonEmpty.style.display = 'none';
    comparisonContent.style.display = 'block';
    formEmpty.style.display = 'none';
    formContent.style.display = 'flex';

    // 詳細情報
    container.querySelector('#detail-order-id').textContent = row.受注データID || row.order_id || '--';
    container.querySelector('#detail-field-name').textContent = row.検証項目 || row.extracted_fields || '--';
    container.querySelector('#detail-score').textContent = (row.総合スコア || row.overall_confidence || 0) + ' / 100';
    container.querySelector('#detail-warning-level').textContent = row.警告レベル || (row.警告フラグ ? '警告あり' : 'なし');

    // 修正前後比較
    const beforeValue = row.検証値 || row.raw_ocr_text || '--';
    const afterValue = container.querySelector('#form-corrected-value').value || beforeValue;
    container.querySelector('#comparison-before').textContent = beforeValue;
    container.querySelector('#comparison-after').textContent = afterValue;

    // フォームリセット
    container.querySelector('#form-corrected-value').value = '';
    container.querySelector('#form-correction-reason').value = '';
    container.querySelector('#form-correction-comment').value = '';
  }

  // 修正値入力時に比較更新
  container.querySelector('#form-corrected-value').addEventListener('input', (e) => {
    if (selectedRow) {
      container.querySelector('#comparison-after').textContent = e.target.value || '--';
    }
  });

  // キャンセル
  container.querySelector('#btn-cancel-edit').addEventListener('click', () => {
    selectedRow = null;
    container.querySelector('#detail-empty').style.display = 'block';
    container.querySelector('#detail-content').style.display = 'none';
    container.querySelector('#comparison-empty').style.display = 'block';
    container.querySelector('#comparison-content').style.display = 'none';
    container.querySelector('#form-empty').style.display = 'block';
    container.querySelector('#form-content').style.display = 'none';
  });

  // 5. 修正確定
  container.querySelector('#btn-save-correction').addEventListener('click', async () => {
    if (!selectedRow) return;

    const correctedValue = container.querySelector('#form-corrected-value').value.trim();
    const reason = container.querySelector('#form-correction-reason').value;
    const comment = container.querySelector('#form-correction-comment').value.trim();

    if (!correctedValue) {
      alert('修正値を入力してください');
      return;
    }
    if (!reason) {
      alert('修正理由を選択してください');
      return;
    }

    // 修正履歴を保存
    const correctionRecord = {
      受注データID: selectedRow.受注データID || selectedRow.order_id,
      修正項目名: selectedRow.検証項目 || selectedRow.extracted_fields,
      修正前値: selectedRow.検証値 || selectedRow.raw_ocr_text,
      修正後値: correctedValue,
      修正理由: reason,
      修正備考: comment,
      修正ユーザーID: 'current-user-id',
      修正日時: new Date().toISOString(),
      検証結果ID: selectedRow.id || selectedRow.信頼度スコアID
    };

    const saved = await window.aivicApi.save(correctionHistoryTableIdx, correctionRecord);
    if (saved) {
      alert('修正が確定されました');
      container.querySelector('#btn-cancel-edit').click();
      await loadInitialData();
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tableIndex = 0; // 入力漏れ検出結果テーブル
  const tbody = container.querySelector("#record-tbody");
