      const id = tr.dataset.id;
      currentRecord = allRecords.find(r => r.id === id);
      if (currentRecord) {
        showDetail(currentRecord);
      }
    }
  });

  // 詳細表示関数
  function showDetail(record) {
    detailEmpty.style.display = "none";
    detailContent.style.display = "block";
    formSection.style.display = "block";

    container.querySelector("#detail-order-id").textContent = record.受注ID || "—";
    container.querySelector("#detail-field-name").textContent = record.漏れ項目名 || "—";
    container.querySelector("#detail-detected-at").textContent = record.検出日時 ? new Date(record.検出日時).toLocaleString("ja-JP") : "—";

    const confidence = record.信頼度スコア || 0;
    container.querySelector("#detail-confidence-bar").style.width = confidence + "%";
    container.querySelector("#detail-confidence-text").textContent = confidence + "%";

    const priorityMap = { "高": "P1", "中": "P2", "低": "P3" };
    container.querySelector("#detail-priority").textContent = priorityMap[record.重要度] || "—";

    // OCR提案表示
    if (record.ocr_提案値) {
      ocrSuggestion.style.display = "block";
      container.querySelector("#ocr-suggestion-value").textContent = record.ocr_提案値;
    } else {
      ocrSuggestion.style.display = "none";
    }

    // フォーム初期化
    container.querySelector("#input-correction-value").value = "";
    container.querySelector("#select-correction-reason").value = "";
    container.querySelector("#textarea-correction-note").value = "";
  }

  // 4. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const orderId = container.querySelector("#filter-order-id").value.toLowerCase();
    const severity = container.querySelector("#filter-severity").value;
    const status = container.querySelector("#filter-status").value;

    const filtered = allRecords.filter(r => {
      const matchId = !orderId || (r.受注ID || "").toLowerCase().includes(orderId);
      const matchSeverity = !severity || r.重要度 === severity;
      const matchStatus = !status || r.検出ステータス === status;
      return matchId && matchSeverity && matchStatus;
    });

    renderRows(filtered);
  });

  // 5. OCR提案を使用
  container.querySelector("#btn-use-ocr").addEventListener("click", () => {
    if (currentRecord && currentRecord.ocr_提案値) {
      container.querySelector("#input-correction-value").value = currentRecord.ocr_提案値;
    }
  });

  // 6. 修正保存
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    if (!currentRecord) return;

    const correctionValue = container.querySelector("#input-correction-value").value.trim();
    const correctionReason = container.querySelector("#select-correction-reason").value;
    const correctionNote = container.querySelector("#textarea-correction-note").value.trim();

    if (!correctionValue || !correctionReason) {
      alert("修正値と修正理由を入力してください");
      return;
    }

    // 修正履歴を保存（テーブルインデックス 1 と仮定）
    const correctionRecord = {
      受注データID: currentRecord.受注ID,
      修正項目名: currentRecord.漏れ項目名,
      修正前値: "",
      修正後値: correctionValue,
      修正理由: correctionReason,
      修正備考: correctionNote,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString(),
      検証結果ID: currentRecord.id
    };

    const saved = await window.aivicApi.save(1, correctionRecord);
    if (saved) {
      // 入力漏れ検出結果を「完了」に更新
      await window.aivicApi.update(tableIndex, currentRecord.id, { 検出ステータス: "完了", 修正済みフラグ: true, 修正日時: new Date().toISOString() });

      // 一覧を再読み込み
      window.aivicApi.list(tableIndex).then(renderRows);

      alert("修正内容を保存しました");
      detailEmpty.style.display = "block";
      detailContent.style.display = "none";
      formSection.style.display = "none";
    }
  });

  // 7. キャンセル
  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    detailEmpty.style.display = "block";
    detailContent.style.display = "none";
    formSection.style.display = "none";
    currentRecord = null;
  });

  // 8. 優先度リスト参照
  container.querySelector("#btn-priority-list").addEventListener("click", () => {
    window.showScreen("scr-1781413354977");
  });

  // 9. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(tableIndex);
    if (!rows || rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "漏れ項目名", "漏れ項目区分", "重要度", "信頼度スコア", "検出ステータス", "修正済みフラグ", "検出日時"];
    const csv = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(r => [
        r.受注ID || "",
        r.漏れ項目名 || "",
        r.漏れ項目区分 || "",
        r.重要度 || "",
        r.信頼度スコア || "",
        r.検出ステータス || "",
        r.修正済みフラグ ? "○" : "×",
        r.検出日時 ? new Date(r.検出日時).toLocaleString("ja-JP") : ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "入力漏れ検出結果_" + new Date().toISOString().split("T")[0] + ".csv";
    link.click();
  });
}

function(container, apiUrl, tables) {
  const tableIndex = 0; // 受注データ検証結果テーブル
  let allRows = [];
  let currentPage = 0;
  const rowsPerPage = 10;

  // ステータスカラーマップ
  const statusColorMap = {
    '合格': '#4caf50',
    '不合格': '#f44336',
    '警告': '#ff9800',
    '保留': '#2196f3'
  };

  const importanceColorMap = {
    '致命的': '#d32f2f',
    '高': '#f57c00',
    '中': '#fbc02d',
    '低': '#7cb342'
  };

  // 1. 再描画関数
  function renderRows(rows) {
    allRows = rows;
    currentPage = 0;
    renderPage();
  }

  function renderPage() {
    const tbody = container.querySelector('#validation-tbody');
    const start = currentPage * rowsPerPage;
    const end = start + rowsPerPage;
    const pageRows = allRows.slice(start, end);

    if (pageRows.length === 0) {
      tbody.innerHTML = '<tr style="text-align: center; color: var(--text-muted); padding: 20px;"><td colspan="8">検証結果がありません</td></tr>';
      updatePagination();
      return;
    }

    tbody.innerHTML = pageRows.map(r => {
      const statusColor = statusColorMap[r.検証ステータス] || '#999';
      const importanceColor = importanceColorMap[r.重要度] || '#999';
      const priorityLabel = r.修正優先度 ? `P${r.修正優先度}` : '-';

      return `
        <tr data-id="${r.検証結果ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05); hover: background: rgba(255,255,255,0.02);">
          <td style="padding: 8px; color: var(--text);">${(r.受注データID || '').substring(0, 8)}</td>
          <td style="padding: 8px; color: var(--text);">${r.チャネル名 || '-'}</td>
          <td style="padding: 8px;">
            <span style="display: inline-block; padding: 3px 8px; background: ${statusColor}20; color: ${statusColor}; border-radius: 3px; font-size: 11px; font-weight: 600;">
              ${r.検証ステータス || '-'}
            </span>
          </td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${r.総合スコア || '-'}</td>
          <td style="padding: 8px; color: var(--text); max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.エラーメッセージ || ''}">
            ${r.エラーメッセージ ? r.エラーメッセージ.substring(0, 30) + '...' : '-'}
          </td>
          <td style="padding: 8px;">
            <span style="display: inline-block; padding: 3px 8px; background: ${importanceColor}20; color: ${importanceColor}; border-radius: 3px; font-size: 11px; font-weight: 600;">
              ${r.重要度 || '-'}
            </span>
          </td>
          <td style="padding: 8px; text-align: center; color: var(--text); font-weight: 600;">${priorityLabel}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.検証結果ID}" style="padding: 4px 8px; font-size: 11px; margin-right: 4px;">詳細</button>
            <button class="action-btn secondary edit-btn" data-id="${r.検証結果ID}" style="padding: 4px 8px; font-size: 11px;">修正</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePagination();
  }

  function updatePagination() {
    const totalPages = Math.ceil(allRows.length / rowsPerPage);
    container.querySelector('#pagination-info').textContent = `${currentPage + 1} / ${totalPages || 1}`;
    container.querySelector('[data-testid="pagination-prev"]').disabled = currentPage === 0;
    container.querySelector('[data-testid="pagination-next"]').disabled = currentPage >= totalPages - 1;
  }

  // KPI 更新関数
  function updateKPIs(rows) {
    const passed = rows.filter(r => r.検証ステータス === '合格').length;
    const failed = rows.filter(r => r.検証ステータス === '不合格').length;
    const warning = rows.filter(r => r.検証ステータス === '警告').length;

    container.querySelector('[data-testid="kpi-passed-count"]').textContent = passed;
    container.querySelector('[data-testid="kpi-failed-count"]').textContent = failed;
    container.querySelector('[data-testid="kpi-warning-count"]').textContent = warning;

    // エラー重要度別
    const critical = rows.filter(r => r.重要度 === '致命的').length;
    const high = rows.filter(r => r.重要度 === '高').length;
    const medium = rows.filter(r => r.重要度 === '中').length;
    const low = rows.filter(r => r.重要度 === '低').length;

    container.querySelector('[data-testid="error-critical"]').textContent = critical;
    container.querySelector('[data-testid="error-high"]').textContent = high;
    container.querySelector('[data-testid="error-medium"]').textContent = medium;
    container.querySelector('[data-testid="error-low"]').textContent = low;
  }

  // 信頼度スコア分布グラフ
  function drawConfidenceChart(rows) {
    const canvas = container.querySelector('#confidence-chart');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // スコア分布を計算（0-20, 20-40, 40-60, 60-80, 80-100）
    const bins = [0, 0, 0, 0, 0];
    rows.forEach(r => {
      const score = r.総合スコア || 0;
      if (score < 20) bins[0]++;
      else if (score < 40) bins[1]++;
      else if (score < 60) bins[2]++;
      else if (score < 80) bins[3]++;
      else bins[4]++;
    });

    const maxBin = Math.max(...bins, 1);
    const barWidth = canvas.width / 5 - 8;
    const barSpacing = 8;
    const colors = ['#d32f2f', '#f57c00', '#fbc02d', '#7cb342', '#4caf50'];
    const labels = ['0-20', '20-40', '40-60', '60-80', '80-100'];

    ctx.fillStyle = 'rgba(255,255,255,0.05)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    bins.forEach((bin, i) => {
      const x = i * (barWidth + barSpacing) + barSpacing;
      const barHeight = (bin / maxBin) * (canvas.height - 40);
      const y = canvas.height - barHeight - 20;

      // バー
      ctx.fillStyle = colors[i];
      ctx.fillRect(x, y, barWidth, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(labels[i], x + barWidth / 2, canvas.height - 5);

      // 値
      ctx.fillStyle = '#d0e4ff';
      ctx.font = 'bold 12px sans-serif';
      ctx.fillText(bin, x + barWidth / 2, y - 5);
    });
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(tableIndex).then(rows => {
    if (!rows || rows.length === 0) {
      rows = tables[tableIndex]?.records || [];
    }
    renderRows(rows);
    updateKPIs(rows);
    drawConfidenceChart(rows);
  });

  // 3. 検索ボタン
  container.querySelector('[data-testid="filter-search-button"]').addEventListener('click', async () => {
    const dateStart = container.querySelector('[data-testid="filter-date-start"]').value;
    const dateEnd = container.querySelector('[data-testid="filter-date-end"]').value;
    const channel = container.querySelector('[data-testid="filter-channel"]').value;

    const rows = await window.aivicApi.list(tableIndex) || tables[tableIndex]?.records || [];

    const filtered = rows.filter(r => {
      if (dateStart && new Date(r.検証実行日時) < new Date(dateStart)) return false;
      if (dateEnd && new Date(r.検証実行日時) > new Date(dateEnd)) return false;
      if (channel && r.チャネル名 !== channel) return false;
      return true;
    });

    renderRows(filtered);
    updateKPIs(filtered);
    drawConfidenceChart(filtered);
  });

  // 4. ページネーション
  container.querySelector('[data-testid="pagination-prev"]').addEventListener('click', () => {
    if (currentPage > 0) {
      currentPage--;
      renderPage();
    }
  });

  container.querySelector('[data-testid="pagination-next"]').addEventListener('click', () => {
    const totalPages = Math.ceil(allRows.length / rowsPerPage);
    if (currentPage < totalPages - 1) {
      currentPage++;
      renderPage();
    }
  });

  // 5. CSV エクスポート
  container.querySelector('[data-testid="export-csv-button"]').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(tableIndex) || tables[tableIndex]?.records || [];
    if (rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['受注ID', 'チャネル', '検証ステータス', '信頼度スコア', 'エラー内容', '重要度', '修正優先度', '検証実行日時'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => [
        (r.受注データID || '').substring(0, 8),
        r.チャネル名 || '',
        r.検証ステータス || '',
        r.総合スコア || '',
        `"${(r.エラーメッセージ || '').replace(/"/g, '""')}"`,
        r.重要度 || '',
        r.修正優先度 || '',
        r.検証実行日時 || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation-report-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 6. 詳細表示・修正ボタン
  container.addEventListener('click', e => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const row = allRows.find(r => r.検証結果ID === id);
      if (row) {
        const detailContent = container.querySelector('#detail-content');
        detailContent.innerHTML = `
          <div><strong>受注ID:</strong> ${(row.受注データID || '').substring(0, 8)}</div>
          <div><strong>チャネル:</strong> ${row.チャネル名 || '-'}</div>
          <div><strong>検証ステータス:</strong> ${row.検証ステータス || '-'}</div>
          <div><strong>信頼度スコア:</strong> ${row.総合スコア || '-'}</div>
          <div><strong>エラーコード:</strong> ${row.エラーコード || '-'}</div>
          <div><strong>エラーメッセージ:</strong> ${row.エラーメッセージ || '-'}</div>
          <div><strong>検証項目:</strong> ${row.検証項目 || '-'}</div>
          <div><strong>重要度:</strong> ${row.重要度 || '-'}</div>
          <div><strong>対応状況:</strong> ${row.対応状況 || '-'}</div>
        `;
        container.querySelector('#detail-modal').style.display = 'flex';
      }
    }

    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const id = editBtn.dataset.id;
      window.showScreen('scr-1781413282852'); // 受注データ詳細確認・修正画面へ
    }
  });

  // 7. モーダル閉じる
  container.querySelector('[data-testid="detail-close-button"]').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  container.querySelector('[data-testid="detail-edit-button"]').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
    window.showScreen('scr-1781413282852'); // 受注データ詳細確認・修正画面へ
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#result-tbody");
  const noDataMsg = container.querySelector("#no-data-message");
  const scoreMinSlider = container.querySelector("#score-min-slider");
  const scoreMaxSlider = container.querySelector("#score-max-slider");
  const scoreMinDisplay = container.querySelector("#score-min-display");
  const scoreMaxDisplay = container.querySelector("#score-max-display");
  const inputMinScore = container.querySelector("#input-min-score");
  const inputMaxScore = container.querySelector("#input-max-score");

  let allRows = [];

  // スコアスライダーの同期
  scoreMinSlider.addEventListener("input", () => {
    const minVal = parseInt(scoreMinSlider.value);
    const maxVal = parseInt(scoreMaxSlider.value);
    if (minVal > maxVal) {
      scoreMinSlider.value = maxVal;
    }
    scoreMinDisplay.textContent = scoreMinSlider.value;
    inputMinScore.value = scoreMinSlider.value;
  });

  scoreMaxSlider.addEventListener("input", () => {
    const minVal = parseInt(scoreMinSlider.value);
    const maxVal = parseInt(scoreMaxSlider.value);
    if (maxVal < minVal) {
      scoreMaxSlider.value = minVal;
    }
    scoreMaxDisplay.textContent = scoreMaxSlider.value;
    inputMaxScore.value = scoreMaxSlider.value;
  });

  inputMinScore.addEventListener("change", () => {
    const val = Math.max(0, Math.min(100, parseInt(inputMinScore.value) || 0));
    scoreMinSlider.value = val;
    scoreMinDisplay.textContent = val;
  });

  inputMaxScore.addEventListener("change", () => {
    const val = Math.max(0, Math.min(100, parseInt(inputMaxScore.value) || 100));
    scoreMaxSlider.value = val;
    scoreMaxDisplay.textContent = val;
  });

  // 再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noDataMsg.style.display = "block";
      return;
    }
    noDataMsg.style.display = "none";
    tbody.innerHTML = rows.map(r => {
      const scoreColor = r.総合スコア >= 80 ? "#4ade80" : r.総合スコア >= 50 ? "#fbbf24" : "#ef4444";
      const warningBadge = r.警告フラグ ? `<span style="background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600;">警告</span>` : `<span style="color: var(--text-muted); font-size: 10px;">-</span>`;
      return `
        <tr data-id="${r.受注データID || r.id}" style="border-bottom: 1px solid var(--border); cursor: pointer;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${r.受注データID || "-"}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: ${scoreColor}; font-weight: 600;">${r.総合スコア || 0}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${r.完全性スコア || 0}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${r.正確性スコア || 0}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${r.一貫性スコア || 0}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${r.検証ステータス || "-"}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${r.チャネル || "-"}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); text-align: center;">${warningBadge}</td>
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text-muted); font-size: 11px;">${r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString('ja-JP') : "-"}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="detail-btn" data-id="${r.受注データID || r.id}" style="background: transparent; color: var(--primary); border: none; cursor: pointer; font-size: 11px; text-decoration: underline; padding: 2px 6px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ表示
  if (tables[0] && tables[0].records) {
    allRows = tables[0].records;
    renderRows(allRows);
  }

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const minScore = parseInt(scoreMinSlider.value);
    const maxScore = parseInt(scoreMaxSlider.value);
    const status = container.querySelector("#filter-status").value;
    const channel = container.querySelector("#filter-channel").value;
    const validation = container.querySelector("#filter-validation").value;
    const correction = container.querySelector("#filter-correction").value;
    const duplicate = container.querySelector("#filter-duplicate").value;
    const channelConflict = container.querySelector("#filter-channel-conflict").value;
    const missing = container.querySelector("#filter-missing").value;
    const ocrConfidence = container.querySelector("#filter-ocr-confidence").value;
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;

    let filtered = allRows.filter(r => {
      const score = r.総合スコア || 0;
      if (score < minScore || score > maxScore) return false;
      if (status && r.検証ステータス !== status) return false;
      if (channel && r.チャネル !== channel) return false;
      if (validation && r.検証結果 !== validation) return false;
      if (correction === "有" && !r.修正履歴有無) return false;
      if (correction === "無" && r.修正履歴有無) return false;
      if (duplicate === "あり" && !r.重複検出フラグ) return false;
      if (duplicate === "なし" && r.重複検出フラグ) return false;
      if (channelConflict === "あり" && !r.チャネル間矛盾フラグ) return false;
      if (channelConflict === "なし" && r.チャネル間矛盾フラグ) return false;
      if (missing === "あり" && !r.入力漏れ検出フラグ) return false;
      if (missing === "なし" && r.入力漏れ検出フラグ) return false;
      if (ocrConfidence === "高" && (r.AI_OCR信頼度 || 0) < 80) return false;
      if (ocrConfidence === "中" && ((r.AI_OCR信頼度 || 0) < 50 || (r.AI_OCR信頼度 || 0) >= 80)) return false;
      if (ocrConfidence === "低" && (r.AI_OCR信頼度 || 0) >= 50) return false;
      if (dateFrom && r.検証実行日時 && new Date(r.検証実行日時) < new Date(dateFrom)) return false;
      if (dateTo && r.検証実行日時 && new Date(r.検証実行日時) > new Date(dateTo + "T23:59:59")) return false;
      return true;
    });

    renderRows(filtered);
  });

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    scoreMinSlider.value = 0;
    scoreMaxSlider.value = 100;
    scoreMinDisplay.textContent = "0";
    scoreMaxDisplay.textContent = "100";
    inputMinScore.value = 0;
    inputMaxScore.value = 100;
    container.querySelector("#filter-status").value = "";
    container.querySelector("#filter-channel").value = "";
    container.querySelector("#filter-validation").value = "";
    container.querySelector("#filter-correction").value = "";
    container.querySelector("#filter-duplicate").value = "";
    container.querySelector("#filter-channel-conflict").value = "";
    container.querySelector("#filter-missing").value = "";
    container.querySelector("#filter-ocr-confidence").value = "";
    container.querySelector("#filter-date-from").value = "";
    container.querySelector("#filter-date-to").value = "";
    renderRows(allRows);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", () => {
    if (!allRows || allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }
    const headers = ["受注データID", "総合スコア", "完全性スコア", "正確性スコア", "一貫性スコア", "検証ステータス", "チャネル", "警告フラグ", "検証実行日時"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...allRows.map(r => [
        r.受注データID || "",
        r.総合スコア || 0,
        r.完全性スコア || 0,
        r.正確性スコア || 0,
        r.一貫性スコア || 0,
        r.検証ステータス || "",
        r.チャネル || "",
        r.警告フラグ ? "はい" : "いいえ",
        r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString('ja-JP') : ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `信頼度スコア_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 詳細ボタン（イベントデリゲーション）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面へ遷移
    }
  });
}

