          <button data-testid="detail-view-button" class="action-btn" style="flex: 1; padding: 6px; font-size: 11px;">詳細確認</button>
          <button data-testid="detail-edit-button" class="action-btn secondary" style="flex: 1; padding: 6px; font-size: 11px;">修正</button>
        </div>
      </div>
    `;
    // 詳細確認ボタン
    container.querySelector("[data-testid='detail-view-button']").addEventListener("click", () => {
      window.showScreen("scr-1781413282852");
    });
    // 修正ボタン
    container.querySelector("[data-testid='detail-edit-button']").addEventListener("click", () => {
      window.showScreen("scr-1781413686599");
    });
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allRows = rows || tables[0].records || [];
    renderRows(allRows);
  });

  // 3. 検索ボタン
  searchBtn.addEventListener("click", () => {
    let filtered = allRows;
    const scoreMin = parseInt(scoreMinInput.value) || 0;
    const scoreMax = parseInt(scoreMaxInput.value) || 100;
    const channel = channelFilter.value;
    const status = statusFilter.value;
    const warningLevel = warningLevelFilter.value;
    const orderId = orderIdSearch.value.toLowerCase();

    filtered = filtered.filter(r => {
      const score = r.総合スコア || 0;
      const matchScore = score >= scoreMin && score <= scoreMax;
      const matchChannel = !channel || r.チャネル === channel;
      const matchStatus = !status || r.検証ステータス === status;
      const matchWarning = !warningLevel || r.警告レベル === warningLevel;
      const matchOrderId = !orderId || (r.受注データID || "").toLowerCase().includes(orderId);
      return matchScore && matchChannel && matchStatus && matchWarning && matchOrderId;
    });
    renderRows(filtered);
  });

  // 4. リセットボタン
  resetBtn.addEventListener("click", () => {
    scoreMinInput.value = "";
    scoreMaxInput.value = "";
    channelFilter.value = "";
    statusFilter.value = "";
    warningLevelFilter.value = "";
    orderIdSearch.value = "";
    renderRows(allRows);
  });

  // 5. ソートボタン
  sortAscBtn.addEventListener("click", () => {
    const sorted = [...allRows].sort((a, b) => (a.総合スコア || 0) - (b.総合スコア || 0));
    renderRows(sorted);
  });

  sortDescBtn.addEventListener("click", () => {
    const sorted = [...allRows].sort((a, b) => (b.総合スコア || 0) - (a.総合スコア || 0));
    renderRows(sorted);
  });

  // 6. CSVエクスポート
  exportBtn.addEventListener("click", () => {
    if (allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }
    const headers = ["受注ID", "総合スコア", "完全性", "正確性", "一貫性", "チャネル", "ステータス", "警告レベル", "計算日時"];
    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...allRows.map(r => [
        r.受注データID || "",
        r.総合スコア || 0,
        r.完全性スコア || 0,
        r.正確性スコア || 0,
        r.一貫性スコア || 0,
        r.チャネル || "",
        r.検証ステータス || "",
        r.警告レベル || "",
        r.スコア計算日時 ? new Date(r.スコア計算日時).toLocaleString('ja-JP') : ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "trust_score_export.csv";
    link.click();
  });

  // 7. 行クリック（詳細表示）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }
  });

  // 8. 行ダブルクリック（詳細確認画面へ遷移）
  tbody.addEventListener("dblclick", e => {
    const row = e.target.closest("tr");
    if (row) {
      window.showScreen("scr-1781413282852");
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=受注データ修正履歴, 1=受注データ検証結果, 2=信頼度スコア, 3=連携承認フロー

  // 修正履歴テーブルの初期データを取得
  let correctionHistoryRows = (tables[0] && tables[0].records) || [];
  let validationResultRows = (tables[1] && tables[1].records) || [];
  let trustScoreRows = (tables[2] && tables[2].records) || [];
  let approvalFlowRows = (tables[3] && tables[3].records) || [];

  // 修正履歴タイムラインを再描画する関数
  function renderHistoryTimeline(rows) {
    const timelineContainer = container.querySelector('[data-testid="修正履歴"]')?.parentElement || 
                              container.querySelector('div:has(> div:nth-child(1):contains("修正履歴"))');
    if (!timelineContainer) return;

    const historyDiv = timelineContainer.querySelector('div[style*="max-height: 200px"]');
    if (!historyDiv) return;

    historyDiv.innerHTML = rows.slice(0, 5).map(row => `
      <div style="display: flex; gap: 10px; margin-bottom: 12px; padding-bottom: 12px; border-bottom: 1px solid rgba(255,255,255,0.08);">
        <div style="width: 3px; background: ${row.修正理由 === '入力誤り' ? '#4caf50' : row.修正理由 === '検証エラー' ? '#ff9800' : '#2196f3'}; border-radius: 2px; flex-shrink: 0;"></div>
        <div style="flex: 1;">
          <div style="color: var(--text); font-weight: 600;">${row.修正項目名 || '修正'}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${row.修正日時 || '日時不明'} | ${row.修正ユーザーID || 'ユーザー不明'}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 4px;">${row.修正前値 || ''} → ${row.修正後値 || ''}</div>
        </div>
      </div>
    `).join('');
  }

  // 初期描画
  renderHistoryTimeline(correctionHistoryRows);

  // 保存ボタンのイベントリスナー
  container.querySelector('[data-testid="save-button"]').addEventListener('click', async () => {
    const reason = container.querySelector('[data-testid="correction-reason"]').value;
    const notes = container.querySelector('[data-testid="correction-notes"]').value;

    if (!reason) {
      alert('修正理由を選択してください');
      return;
    }

    // 修正履歴を保存
    const correctionData = {
      受注データID: 'ORD-2025-001234', // 実際にはフォームから取得
      修正項目名: '受注金額',
      修正前値: '¥150,000',
      修正後値: '¥180,000',
      修正理由: reason,
      修正備考: notes,
      修正ユーザーID: '田中太郎',
      修正日時: new Date().toISOString(),
    };

    const saved = await window.aivicApi.save(0, correctionData);
    if (saved) {
      alert('修正内容を保存しました');
      // 履歴を再読み込み
      const updated = await window.aivicApi.list(0);
      if (updated) {
        correctionHistoryRows = updated;
        renderHistoryTimeline(correctionHistoryRows);
      }
      // フォームをリセット
      container.querySelector('[data-testid="correction-reason"]').value = '';
      container.querySelector('[data-testid="correction-notes"]').value = '';
    }
  });

  // キャンセルボタンのイベントリスナー
  container.querySelector('[data-testid="cancel-button"]').addEventListener('click', () => {
    if (confirm('修正内容を破棄してもよろしいですか？')) {
      window.showScreen('scr-1781413282852'); // 受注データ詳細確認・修正画面へ遷移
    }
  });

  // 定期的に修正履歴を更新（オプション）
  setInterval(async () => {
    const updated = await window.aivicApi.list(0);
    if (updated && updated.length > correctionHistoryRows.length) {
      correctionHistoryRows = updated;
      renderHistoryTimeline(correctionHistoryRows);
    }
  }, 5000);
}

function(container, apiUrl, tables) {
  // テーブルインデックス（データ構造から推測）
  const DUPLICATE_RESULTS_IDX = 0;  // 重複受注検出結果
  const CHANNEL_CONFLICTS_IDX = 1;  // チャネル間矛盾検出結果
  const VALIDATION_RESULTS_IDX = 2; // 受注データ検証結果
  const CORRECTION_HISTORY_IDX = 3; // 受注データ修正履歴
  const CONFIDENCE_SCORES_IDX = 4;  // 信頼度スコア

  let allDuplicates = [];
  let selectedDuplicate = null;

  // ============ 1. 重複グループ一覧の再描画 ============
  function renderDuplicateGroups(duplicates) {
    const list = container.querySelector("#duplicate-groups-list");
    list.innerHTML = duplicates.map(dup => `
      <div class="duplicate-group-card" data-id="${dup.重複受注検出結果ID || dup.id}" style="
        padding: 10px 12px;
        margin-bottom: 8px;
        background: var(--bg-card);
        border: 1px solid rgba(255,255,255,0.1);
        border-radius: 4px;
        cursor: pointer;
        transition: all 0.2s;
      " onmouseover="this.style.borderColor='var(--primary)'; this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.borderColor='rgba(255,255,255,0.1)'; this.style.background='var(--bg-card)'">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 6px;">
          <div style="font-size: 12px; font-weight: 600; color: var(--text);">
            ${dup.主受注ID ? dup.主受注ID.substring(0, 8) : '---'} ↔ ${dup.副受注ID ? dup.副受注ID.substring(0, 8) : '---'}
          </div>
          <div style="font-size: 11px; padding: 2px 6px; border-radius: 3px; background: ${
            dup.マッチング信頼度 >= 90 ? 'rgba(76, 158, 255, 0.2); color: #4a9eff;' :
            dup.マッチング信頼度 >= 70 ? 'rgba(255, 193, 7, 0.2); color: #ffc107;' :
            'rgba(255, 106, 0, 0.2); color: #ff6a00;'
          }">
            ${dup.マッチング信頼度 || 0}%
          </div>
        </div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">
          ${dup.マッチング理由 || '理由未記載'}
        </div>
        <div style="font-size: 11px; color: var(--text-muted);">
          ステータス: <span style="color: var(--text); font-weight: 500;">${dup.検出ステータス || '未確認'}</span>
        </div>
      </div>
    `).join("");
  }

  // ============ 2. 詳細パネルの表示 ============
  function showDetailPanel(duplicate) {
    selectedDuplicate = duplicate;
    const template = container.querySelector("#detail-panel-template");
    const detailPanel = container.querySelector("#detail-panel");
    const emptyState = container.querySelector("#empty-state");

    // テンプレートから新しいパネルを生成
    const newPanel = template.content.cloneNode(true);
    detailPanel.innerHTML = "";
    detailPanel.appendChild(newPanel);

    // 信頼度スコア表示
    container.querySelector("#detail-confidence").textContent = `${duplicate.マッチング信頼度 || 0}%`;

    // ステータス表示
    const statusEl = container.querySelector("#detail-status");
    statusEl.textContent = duplicate.検出ステータス || "未確認";
    statusEl.style.color = 
      duplicate.検出ステータス === "統合済み" ? "#4a9eff" :
      duplicate.検出ステータス === "確認済み" ? "#7cb342" :
      duplicate.検出ステータス === "誤検出" ? "#ff6a00" : "var(--text-muted)";

    // マッチング理由
    container.querySelector("#detail-reason").textContent = `マッチング理由: ${duplicate.マッチング理由 || "未記載"}`;

    // 比較テーブルの生成（主受注と副受注の項目を並べて表示）
    const comparisonItems = [
      { label: "受注ID", key: "受注ID" },
      { label: "顧客名", key: "顧客名" },
      { label: "受注金額", key: "受注金額" },
      { label: "受注数量", key: "受注数量" },
      { label: "受注日時", key: "受注日時" },
      { label: "チャネル", key: "チャネル" },
      { label: "配送先", key: "配送先" },
    ];

    const tbody = container.querySelector("#detail-comparison-tbody");
    tbody.innerHTML = comparisonItems.map(item => {
      const mainVal = duplicate.主受注データ?.[item.key] || "---";
      const subVal = duplicate.副受注データ?.[item.key] || "---";
      const isMismatch = mainVal !== subVal && mainVal !== "---" && subVal !== "---";
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.1);">
          <td style="padding: 8px 10px; color: var(--text-muted); font-weight: 500; background: rgba(0,0,0,0.1);">${item.label}</td>
          <td style="padding: 8px 10px; color: var(--text); ${isMismatch ? 'background: rgba(255, 106, 0, 0.15);' : ''}">${mainVal}</td>
          <td style="padding: 8px 10px; color: var(--text); ${isMismatch ? 'background: rgba(255, 106, 0, 0.15);' : ''}">${subVal}</td>
        </tr>
      `;
    }).join("");

    // チャネル間矛盾の表示
    const conflictDiv = container.querySelector("#channel-conflicts");
    const conflictsList = container.querySelector("#conflicts-list");
    if (duplicate.チャネル間矛盾 && duplicate.チャネル間矛盾.length > 0) {
      conflictDiv.style.display = "block";
      conflictsList.innerHTML = duplicate.チャネル間矛盾.map(c => 
        `<div>• ${c.矛盾タイプ}: ${c.矛盾内容}</div>`
      ).join("");
    } else {
      conflictDiv.style.display = "none";
    }

    // 修正提案
    const suggestion = duplicate.修正提案 || "主受注データを基準に統合することを推奨します。";
    container.querySelector("#detail-suggestion").textContent = suggestion;

    // パネル表示
    detailPanel.style.display = "flex";
    emptyState.style.display = "none";

    // アクションボタンのイベントリスナー
    container.querySelector("#detail-confirm").onclick = () => confirmCorrection(duplicate);
    container.querySelector("#detail-cancel").onclick = () => {
      detailPanel.style.display = "none";
      emptyState.style.display = "flex";
      selectedDuplicate = null;
    };
  }

  // ============ 3. 修正確定処理 ============
  async function confirmCorrection(duplicate) {
    const action = container.querySelector("#detail-action").value;
    const reasonType = container.querySelector("#detail-reason-type").value;
    const notes = container.querySelector("#detail-notes").value;

    if (!action || !reasonType) {
      alert("対応方針と修正理由を選択してください");
      return;
    }

    // 修正履歴を保存
    const correctionData = {
      受注データID: duplicate.主受注ID,
      修正項目名: "重複受注統合",
      修正前値: JSON.stringify({ 主: duplicate.主受注ID, 副: duplicate.副受注ID }),
      修正後値: action === "統合" ? duplicate.主受注ID : duplicate.副受注ID,
      修正理由: reasonType,
      修正備考: notes,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString(),
    };

    const saved = await window.aivicApi.save(CORRECTION_HISTORY_IDX, correctionData);
    if (saved) {
      // 重複検出結果のステータスを更新
      const updateData = {
        検出ステータス: action === "却下" ? "誤検出" : "確認済み",
        対応方針: action,
        確認者ID: "current-user-id",
        確認日時: new Date().toISOString(),
      };
      await window.aivicApi.update(DUPLICATE_RESULTS_IDX, duplicate.重複受注検出結果ID || duplicate.id, updateData);

      alert("修正内容を確定しました");
      // 一覧を再読み込み
      const duplicates = await window.aivicApi.list(DUPLICATE_RESULTS_IDX);
      renderDuplicateGroups(duplicates || []);
      container.querySelector("#detail-panel").style.display = "none";
      container.querySelector("#empty-state").style.display = "flex";
      selectedDuplicate = null;
    }
  }

  // ============ 4. 検索処理 ============
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    const statusFilter = container.querySelector("#filter-status").value;
    const confidenceFilter = container.querySelector("#filter-confidence").value;

    const duplicates = await window.aivicApi.list(DUPLICATE_RESULTS_IDX);
    if (!duplicates) return;

    let filtered = duplicates;

    // キーワード検索
    if (keyword) {
      filtered = filtered.filter(d => 
        (d.主受注ID && d.主受注ID.toLowerCase().includes(keyword)) ||
        (d.副受注ID && d.副受注ID.toLowerCase().includes(keyword)) ||
        (d.マッチング理由 && d.マッチング理由.toLowerCase().includes(keyword))
      );
    }

    // ステータスフィルター
    if (statusFilter) {
      filtered = filtered.filter(d => d.検出ステータス === statusFilter);
    }

    // 信頼度フィルター
    if (confidenceFilter) {
      const [min, max] = confidenceFilter.split("-").map(Number);
      filtered = filtered.filter(d => {
        const score = d.マッチング信頼度 || 0;
        return score >= min && score <= max;
      });
    }

    allDuplicates = filtered;
    renderDuplicateGroups(filtered);
  });

  // ============ 5. CSVエクスポート ============
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const duplicates = await window.aivicApi.list(DUPLICATE_RESULTS_IDX);
    if (!duplicates || duplicates.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["主受注ID", "副受注ID", "マッチング信頼度", "マッチング理由", "検出ステータス", "対応方針", "確認日時"];
    const rows = duplicates.map(d => [
      d.主受注ID || "",
      d.副受注ID || "",
      d.マッチング信頼度 || "",
      d.マッチング理由 || "",
      d.検出ステータス || "",
      d.対応方針 || "",
      d.確認日時 || "",
    ]);

    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")
    ).join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `重複受注検出結果_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // ============ 6. 重複グループ行のクリックイベント ============
  container.addEventListener("click", (e) => {
    const card = e.target.closest(".duplicate-group-card");
    if (card) {
      const id = card.dataset.id;
      const duplicate = allDuplicates.find(d => (d.重複受注検出結果ID || d.id) === id);
      if (duplicate) {
        showDetailPanel(duplicate);
      }
    }
  });

  // ============ 7. 初期データ読み込み ============
  async function initializeScreen() {
    const duplicates = await window.aivicApi.list(DUPLICATE_RESULTS_IDX);
    if (duplicates) {
      allDuplicates = duplicates;
      renderDuplicateGroups(duplicates);
    }
  }

  initializeScreen();
}

function(container, apiUrl, tables) {
