        secondaryDetail.innerHTML = `
          <div><strong>受注ID:</strong> ${selectedDuplicateGroup.副受注ID || '-'}</div>
          <div><strong>顧客名:</strong> ${selectedDuplicateGroup.副顧客名 || '-'}</div>
          <div><strong>受注金額:</strong> ${selectedDuplicateGroup.副受注金額 || '-'}</div>
          <div><strong>受注日時:</strong> ${selectedDuplicateGroup.副受注日時 || '-'}</div>
          <div><strong>チャネル:</strong> ${selectedDuplicateGroup.副チャネル || '-'}</div>
        `;

        // マッチング信頼度・理由表示
        container.querySelector("#matching-confidence").textContent = selectedDuplicateGroup.マッチング信頼度 || '-';
        container.querySelector("#matching-reason").textContent = selectedDuplicateGroup.マッチング理由 || '-';
        container.querySelector("#channel-info").textContent = `${selectedDuplicateGroup.チャネル || '-'} ↔ ${selectedDuplicateGroup.副チャネル || '-'}`;

        // チャネル間矛盾検出結果表示
        const contradictions = tables[CHANNEL_CONTRADICTIONS_IDX]?.records || [];
        const relatedContradictions = contradictions.filter(c => 
          (c.受注ID_1 === selectedDuplicateGroup.主受注ID && c.受注ID_2 === selectedDuplicateGroup.副受注ID) ||
          (c.受注ID_1 === selectedDuplicateGroup.副受注ID && c.受注ID_2 === selectedDuplicateGroup.主受注ID)
        );

        const contradictionList = container.querySelector("#channel-contradiction-list");
        if (relatedContradictions.length > 0) {
          contradictionList.innerHTML = relatedContradictions.map(c => `
            <div style="padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.04);">
              <strong>${c.矛盾タイプ || '-'}:</strong> ${c.矛盾内容 || '-'} (重要度: ${c.重要度 || '-'})
            </div>
          `).join("");
        } else {
          contradictionList.innerHTML = '<div style="color: var(--text-muted);">矛盾なし</div>';
        }

        // 信頼度スコア表示
        const trustScores = tables[TRUST_SCORES_IDX]?.records || [];
        const relatedScore = trustScores.find(s => s.受注データID === selectedDuplicateGroup.主受注ID);
        container.querySelector("#trust-score-display").textContent = relatedScore?.総合スコア || '-';
      }
    }
  });

  // ========== 4. 検索ボタン ==========
  container.querySelector("#btn-search-groups").addEventListener("click", () => {
    const keyword = container.querySelector("#search-duplicate-groups").value.toLowerCase();
    const filtered = allDuplicateGroups.filter(g => 
      JSON.stringify(g).toLowerCase().includes(keyword)
    );
    renderDuplicateGroups(filtered);
  });

  // ========== 5. プレビュー更新ボタン ==========
  container.querySelector("#btn-preview-merge").addEventListener("click", () => {
    if (!selectedDuplicateGroup) {
      alert("グループを選択してください");
      return;
    }

    const mergePolicy = container.querySelector("#merge-policy").value;
    const previewDiv = container.querySelector("#merge-preview");

    let previewText = "";
    if (mergePolicy === "primary") {
      previewText = `主受注データ（ID: ${selectedDuplicateGroup.主受注ID}）を優先して統合します。副受注は削除されます。`;
    } else if (mergePolicy === "secondary") {
      previewText = `副受注データ（ID: ${selectedDuplicateGroup.副受注ID}）を優先して統合します。主受注は削除されます。`;
    } else if (mergePolicy === "merge") {
      previewText = `両受注データを統合します。主受注に副受注の情報を結合し、副受注は削除されます。`;
    } else if (mergePolicy === "manual") {
      previewText = `手動選択モード：各フィールドを個別に選択して統合します。`;
    } else {
      previewText = "統合方針を選択してください";
    }

    previewDiv.innerHTML = `<div>${previewText}</div>`;
  });

  // ========== 6. マージ実行ボタン ==========
  container.querySelector("#btn-execute-merge").addEventListener("click", async () => {
    if (!selectedDuplicateGroup) {
      alert("グループを選択してください");
      return;
    }

    const mergePolicy = container.querySelector("#merge-policy").value;
    if (!mergePolicy) {
      alert("統合方針を選択してください");
      return;
    }

    if (!confirm("マージを実行しますか？")) return;

    try {
      // マージ実行（API呼び出し）
      const mergeData = {
        主受注ID: selectedDuplicateGroup.主受注ID,
        副受注ID: selectedDuplicateGroup.副受注ID,
        統合方針: mergePolicy,
        優先度レベル: container.querySelector("#priority-level").value,
        修正対象優先度: container.querySelector("#correction-priority").value,
        検出ステータス: "統合済み"
      };

      const result = await window.aivicApi.update(DUPLICATE_RESULTS_IDX, selectedDuplicateGroup.id, mergeData);

      if (result) {
        alert("マージが完了しました");
        // 一覧を再読み込み
        const updated = await window.aivicApi.list(DUPLICATE_RESULTS_IDX);
        allDuplicateGroups = updated || [];
        renderDuplicateGroups(allDuplicateGroups);
        selectedDuplicateGroup = null;
        container.querySelector("#primary-order-detail").innerHTML = '<div style="color: var(--text-muted);">選択してください</div>';
        container.querySelector("#secondary-order-detail").innerHTML = '<div style="color: var(--text-muted);">選択してください</div>';
      }
    } catch (err) {
      console.error("マージ実行エラー:", err);
      alert("マージ実行に失敗しました");
    }
  });

  // ========== 7. キャンセルボタン ==========
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("処理をキャンセルしますか？")) {
      selectedDuplicateGroup = null;
      container.querySelector("#primary-order-detail").innerHTML = '<div style="color: var(--text-muted);">選択してください</div>';
      container.querySelector("#secondary-order-detail").innerHTML = '<div style="color: var(--text-muted);">選択してください</div>';
      container.querySelector("#merge-policy").value = "";
      container.querySelector("#priority-level").value = "";
      container.querySelector("#correction-priority").value = "";
      container.querySelector("#merge-preview").innerHTML = '<div style="color: var(--text-muted);">統合方針を選択してください</div>';
    }
  });

  // ========== 8. 承認フロー確認表示 ==========
  function updateApprovalFlowStatus() {
    if (!selectedDuplicateGroup) return;

    const approvalFlows = tables[APPROVAL_FLOW_IDX]?.records || [];
    const relatedFlow = approvalFlows.find(f => f.受注データ_ID === selectedDuplicateGroup.主受注ID);

    const statusDiv = container.querySelector("#approval-flow-status");
    if (relatedFlow) {
      statusDiv.innerHTML = `
        <div><strong>フロー段階:</strong> ${relatedFlow.フロー段階 || '-'}</div>
        <div><strong>現在ステータス:</strong> ${relatedFlow.現在ステータス || '-'}</div>
        <div><strong>承認者:</strong> ${relatedFlow.承認者_ID || '-'}</div>
        <div><strong>期限:</strong> ${relatedFlow.期限日時 || '-'}</div>
      `;
    } else {
      statusDiv.innerHTML = '<div style="color: var(--text-muted);">承認フロー情報なし</div>';
    }

    // 承認者判定履歴表示
    const approvalHistories = tables[APPROVAL_HISTORY_IDX]?.records || [];
    const relatedHistories = approvalHistories.filter(h => h.受注データID === selectedDuplicateGroup.主受注ID);

    const historyDiv = container.querySelector("#approval-history");
    if (relatedHistories.length > 0) {
      historyDiv.innerHTML = relatedHistories.map(h => `
        <div style="padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.04);">
          <strong>${h.判定結果 || '-'}:</strong> ${h.判定理由 || '-'} (${h.判定日時 || '-'})
        </div>
      `).join("");
    } else {
      historyDiv.innerHTML = '<div style="color: var(--text-muted);">履歴なし</div>';
    }
  }

  // 重複グループ選択時に承認フロー更新
  const originalClickHandler = container.addEventListener("click", (e) => {
    const row = e.target.closest(".duplicate-group-row");
    if (row) {
      setTimeout(updateApprovalFlowStatus, 100);
    }
  });
}

function(container, apiUrl, tables) {
  const tableIndex = 0; // 受注データ検証結果テーブル
  let allRows = [];
  let selectedRow = null;

  // ステータス色マッピング
  const statusColors = {
    '合格': '#4ade80',
    '警告': '#facc15',
    '不合格': '#ef4444',
    '保留': '#94a3b8'
