  };

  // 1. テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#validation-tbody');
    tbody.innerHTML = rows.map(r => {
      const statusColor = statusColors[r.検証ステータス] || '#94a3b8';
      const severityColor = severityColors[r.重要度] || '#94a3b8';
      return `
        <tr data-id="${r.検証結果ID}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
          <td style="padding: 8px 12px; color: var(--text-muted); font-family: monospace; font-size: 11px;">${(r.受注データID || '').substring(0, 8)}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-size: 11px; font-weight: 500;">${r.検証ステータス || '-'}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text); font-weight: 600;">${r.信頼度スコア !== undefined ? r.信頼度スコア + '%' : '-'}</td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-family: monospace; font-size: 11px;">${r.エラーコード || '-'}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 11px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.エラーメッセージ || '-'}</td>
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${severityColor}20; color: ${severityColor}; font-size: 10px; font-weight: 500;">${r.重要度 || '-'}</span>
          </td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">${r.チャネル || '-'}</td>
        </tr>
      `;
    }).join('');

    // 統計更新
    const stats = {
      '合格': rows.filter(r => r.検証ステータス === '合格').length,
      '警告': rows.filter(r => r.検証ステータス === '警告').length,
      '不合格': rows.filter(r => r.検証ステータス === '不合格').length
    };
    const avgScore = rows.length > 0 ? Math.round(rows.reduce((sum, r) => sum + (r.信頼度スコア || 0), 0) / rows.length) : 0;

    container.querySelector('[data-testid="stat-pass"]').textContent = stats['合格'];
    container.querySelector('[data-testid="stat-warning"]').textContent = stats['警告'];
    container.querySelector('[data-testid="stat-fail"]').textContent = stats['不合格'];
    container.querySelector('[data-testid="stat-avg-score"]').textContent = avgScore + '%';
    container.querySelector('#record-count').textContent = rows.length;

    // 行クリックで詳細表示
    container.querySelectorAll('#validation-tbody tr').forEach(tr => {
      tr.addEventListener('click', () => {
        selectedRow = rows.find(r => r.検証結果ID === tr.dataset.id);
        showDetail(selectedRow);
      });
    });
  }

  // 2. 詳細パネル表示
  function showDetail(row) {
    if (!row) return;
    const detailPanel = container.querySelector('#detail-panel');
    const noSelection = container.querySelector('#no-selection');

    container.querySelector('#detail-order-id').textContent = (row.受注データID || '').substring(0, 12);
    container.querySelector('#detail-item').textContent = row.検証項目 || '-';
    container.querySelector('#detail-expected').textContent = row.期待値 || '-';
    container.querySelector('#detail-actual').textContent = row.検証値 || '-';

    // 修正提案（簡易版）
    const suggestion = row.検証ステータス === '不合格' 
      ? `${row.検証項目}を「${row.期待値}」に修正してください`
      : row.検証ステータス === '警告'
      ? `${row.検証項目}の値を確認してください`
      : '修正不要です';
    container.querySelector('#detail-suggestion').textContent = suggestion;

    // 関連検出結果（ダミー）
    const relatedList = container.querySelector('#related-list');
    relatedList.innerHTML = `
      <div style="margin-bottom: 4px;">🔗 重複受注検出: 0件</div>
      <div style="margin-bottom: 4px;">🔗 チャネル矛盾: 0件</div>
      <div>🔗 入力漏れ: 0件</div>
    `;

    detailPanel.style.display = 'block';
    noSelection.style.display = 'none';
  }

  // 3. 初期データ読み込み
  window.aivicApi.list(tableIndex).then(rows => {
    allRows = rows || tables[tableIndex]?.records || [];
    // サンプルデータ追加（API未接続時）
    if (allRows.length === 0) {
      allRows = [
        { 検証結果ID: 'vr-001', 受注データID: 'ord-001', 検証ステータス: '不合格', 検証項目: '受注金額', エラーコード: 'ERR_AMOUNT', エラーメッセージ: '金額が負数です', 重要度: '致命的', 信頼度スコア: 25, チャネル: 'WEB', 期待値: '0以上', 検証値: '-1000' },
        { 検証結果ID: 'vr-002', 受注データID: 'ord-002', 検証ステータス: '警告', 検証項目: '顧客名', エラーコード: 'WARN_MISSING', エラーメッセージ: '顧客名が空です', 重要度: '高', 信頼度スコア: 60, チャネル: 'TEL', 期待値: '必須', 検証値: '' },
        { 検証結果ID: 'vr-003', 受注データID: 'ord-003', 検証ステータス: '合格', 検証項目: '配送先住所', エラーコード: null, エラーメッセージ: null, 重要度: null, 信頼度スコア: 95, チャネル: 'STORE', 期待値: '有効な住所', 検証値: '東京都渋谷区' },
        { 検証結果ID: 'vr-004', 受注データID: 'ord-004', 検証ステータス: '不合格', 検証項目: 'メールアドレス', エラーコード: 'ERR_FORMAT', エラーメッセージ: 'メールアドレス形式が不正です', 重要度: '高', 信頼度スコア: 15, チャネル: 'API', 期待値: 'xxx@xxx.xxx', 検証値: 'invalid-email' },
        { 検証結果ID: 'vr-005', 受注データID: 'ord-005', 検証ステータス: '警告', 検証項目: '電話番号', エラーコード: 'WARN_FORMAT', エラーメッセージ: '電話番号の形式が推奨形式と異なります', 重要度: '中', 信頼度スコア: 70, チャネル: 'WEB', 期待値: '0XX-XXXX-XXXX', 検証値: '09012345678' }
      ];
    }
    renderRows(allRows);
  });

  // 4. 検索ボタン
  container.querySelector('[data-testid="search-button"]').addEventListener('click', () => {
    const status = container.querySelector('[data-testid="status-filter"]').value;
    const channel = container.querySelector('[data-testid="channel-filter"]').value;
    const keyword = container.querySelector('[data-testid="search-input"]').value.toLowerCase();

    const filtered = allRows.filter(r => {
      const matchStatus = !status || r.検証ステータス === status;
      const matchChannel = !channel || r.チャネル === channel;
      const matchKeyword = !keyword || 
        (r.受注データID || '').toLowerCase().includes(keyword) ||
        (r.エラーコード || '').toLowerCase().includes(keyword) ||
        (r.エラーメッセージ || '').toLowerCase().includes(keyword);
      return matchStatus && matchChannel && matchKeyword;
    });

    renderRows(filtered);
  });

  // 5. 自動検証実行ボタン
  container.querySelector('[data-testid="auto-validate-button"]').addEventListener('click', async () => {
    const btn = container.querySelector('[data-testid="auto-validate-button"]');
    const originalText = btn.textContent;
    btn.textContent = '検証中...';
    btn.disabled = true;

    // シミュレーション: 2秒後に完了
    await new Promise(resolve => setTimeout(resolve, 2000));

    btn.textContent = originalText;
    btn.disabled = false;
    alert('検証が完了しました');
  });

  // 6. 修正提案適用ボタン
  container.querySelector('[data-testid="apply-suggestion-btn"]').addEventListener('click', async () => {
    if (!selectedRow) return;
    const result = await window.aivicApi.update(tableIndex, selectedRow.検証結果ID, {
      検証ステータス: '合格',
      対応状況: '完了'
    });
    if (result) {
      alert('修正提案を適用しました');
      window.aivicApi.list(tableIndex).then(renderRows);
    }
  });

  // 7. 詳細ボタン（詳細確認・修正画面へ遷移）
  container.querySelector('[data-testid="detail-view-btn"]').addEventListener('click', () => {
    if (!selectedRow) return;
    window.showScreen('scr-1781413282852'); // 受注データ詳細確認・修正画面
  });

  // 8. CSVエクスポート
  container.querySelector('[data-testid="export-csv-btn"]').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(tableIndex) || allRows;
    const headers = ['受注ID', 'ステータス', '信頼度', 'エラーコード', 'エラーメッセージ', '重要度', 'チャネル', '検証日時'];
    const csv = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => [
        r.受注データID || '',
        r.検証ステータス || '',
        r.信頼度スコア || '',
        r.エラーコード || '',
        `"${(r.エラーメッセージ || '').replace(/"/g, '""')}"`,
        r.重要度 || '',
        r.チャネル || '',
        r.検証実行日時 || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv; charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation_results_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 9. ダッシュボードボタン
  container.querySelector('[data-testid="dashboard-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1781413262699'); // 受注データ検証ダッシュボード
  });
}

function(container, apiUrl, tables) {
  // ============================================
  // 1. チャート描画関数
  // ============================================
  function drawChannelErrorChart() {
    const canvas = container.querySelector("#chart-channel-error");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    const channels = ["Web注文", "電話受注", "店舗POS", "API連携"];
    const errorRates = [5.2, 8.4, 6.1, 3.8];
    const barWidth = canvas.width / (channels.length * 1.5);
    const maxRate = 10;
    const chartHeight = canvas.height * 0.8;
    const chartTop = canvas.height * 0.1;

    // 背景
    ctx.fillStyle = "rgba(0,0,0,0.02)";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Y軸ラベル
    ctx.fillStyle = "#9fb0d1";
    ctx.font = "11px sans-serif";
    ctx.textAlign = "right";
    for (let i = 0; i <= 5; i++) {
      const y = chartTop + (chartHeight * (5 - i)) / 5;
      ctx.fillText((i * 2) + "%", canvas.width * 0.08, y + 4);
    }

    // グリッド線
    ctx.strokeStyle = "rgba(255,255,255,0.08)";
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = chartTop + (chartHeight * (5 - i)) / 5;
      ctx.beginPath();
      ctx.moveTo(canvas.width * 0.1, y);
      ctx.lineTo(canvas.width * 0.95, y);
      ctx.stroke();
    }

    // バー描画
    const colors = ["#ff6a00", "#d32f2f", "#f57c00", "#1976d2"];
    channels.forEach((ch, idx) => {
      const x = canvas.width * 0.12 + idx * (barWidth * 1.5);
      const barHeight = (errorRates[idx] / maxRate) * chartHeight;
      const y = chartTop + chartHeight - barHeight;

      ctx.fillStyle = colors[idx];
      ctx.fillRect(x, y, barWidth * 0.8, barHeight);

      // ラベル
      ctx.fillStyle = "#d0e4ff";
      ctx.font = "bold 12px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(errorRates[idx] + "%", x + barWidth * 0.4, y - 6);

      // X軸ラベル
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "11px sans-serif";
      ctx.fillText(ch, x + barWidth * 0.4, canvas.height - 8);
    });
  }

  function drawValidationPieChart() {
    const canvas = container.querySelector("#chart-validation-pie");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // 背景
    ctx.fillStyle = "rgba(0,0,0,0.02)";
    ctx.fillRect(0, canvas.width, canvas.width, canvas.height);

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(canvas.width, canvas.height) * 0.3;

    const data = [
      { label: "合格", value: 1007, color: "#66bb6a" },
      { label: "不合格", value: 84, color: "#ff6a6a" },
      { label: "警告", value: 156, color: "#ffb74d" },
      { label: "保留", value: 0, color: "#9fb0d1" }
    ];

    const total = data.reduce((sum, d) => sum + d.value, 0);
    let currentAngle = -Math.PI / 2;

    data.forEach(d => {
      if (d.value === 0) return;
      const sliceAngle = (d.value / total) * 2 * Math.PI;

      ctx.fillStyle = d.color;
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.65);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.65);
      const percentage = ((d.value / total) * 100).toFixed(1);

      ctx.fillStyle = "#d0e4ff";
      ctx.font = "bold 12px sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(percentage + "%", labelX, labelY);

      currentAngle += sliceAngle;
    });

    // 凡例
    const legendX = canvas.width * 0.65;
    let legendY = canvas.height * 0.15;
    ctx.font = "11px sans-serif";
    ctx.textAlign = "left";
    data.forEach(d => {
      ctx.fillStyle = d.color;
      ctx.fillRect(legendX, legendY, 10, 10);
      ctx.fillStyle = "#d0e4ff";
      ctx.fillText(d.label + " (" + d.value + ")", legendX + 14, legendY + 8);
      legendY += 18;
    });
  }

  // ============================================
  // 2. フィルタ適用関数
  // ============================================
  function applyFilters() {
    const startDate = container.querySelector("[data-testid='period-start']").value;
    const endDate = container.querySelector("[data-testid='period-end']").value;
    const channel = container.querySelector("[data-testid='channel-filter']").value;
    const user = container.querySelector("[data-testid='user-filter']").value;
    const status = container.querySelector("[data-testid='status-filter']").value;

    // ここでは集計データを再計算（実装例）
    console.log("Filters applied:", { startDate, endDate, channel, user, status });

    // チャートを再描画
    setTimeout(() => {
      drawChannelErrorChart();
      drawValidationPieChart();
    }, 100);
  }

  // ============================================
  // 3. リセット関数
  // ============================================
  function resetFilters() {
    container.querySelector("[data-testid='period-start']").value = "";
    container.querySelector("[data-testid='period-end']").value = "";
    container.querySelector("[data-testid='channel-filter']").value = "";
    container.querySelector("[data-testid='user-filter']").value = "";
    container.querySelector("[data-testid='status-filter']").value = "";
    applyFilters();
  }

  // ============================================
  // 4. CSVエクスポート関数
  // ============================================
  function exportCSV() {
    const rows = [
      ["検証ステータス", "件数", "割合", "前期比"],
      ["合格", "1007", "80.8%", "+8.2%"],
      ["不合格", "84", "6.7%", "-2.1%"],
      ["警告", "156", "12.5%", "+3.4%"],
      ["保留", "0", "0.0%", "-"]
    ];

    let csv = "\uFEFF"; // BOM
    csv += rows.map(row => row.map(cell => {
      if (cell.includes(",") || cell.includes('"') || cell.includes("\n")) {
        return '"' + cell.replace(/"/g, '""') + '"';
      }
      return cell;
    }).join(",")).join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "集計結果_" + new Date().toISOString().split("T")[0] + ".csv";
    link.click();
  }

  // ============================================
  // 5. イベントリスナー登録
  // ============================================
  container.querySelector("[data-testid='filter-apply-button']").addEventListener("click", applyFilters);
  container.querySelector("[data-testid='filter-reset-button']").addEventListener("click", resetFilters);
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", exportCSV);

  container.querySelector("[data-testid='detail-report-button']").addEventListener("click", () => {
    window.showScreen("scr-1781413382983"); // 受注データ検証結果レポート画面
  });

  container.querySelector("[data-testid='dashboard-button']").addEventListener("click", () => {
    window.showScreen("scr-1781413262699"); // 受注データ検証ダッシュボード
  });

  // ============================================
  // 6. 初期描画
  // ============================================
  setTimeout(() => {
    drawChannelErrorChart();
    drawValidationPieChart();
  }, 200);
}

function(container, apiUrl, tables) {
  const orderTbody = container.querySelector('#order-tbody');
  const detailPanel = container.querySelector('#detail-basic');
  const issuesList = container.querySelector('#issues-list');
  const missingList = container.querySelector('#missing-list');
  const conflictsList = container.querySelector('#conflicts-list');
  const tabBtns = container.querySelectorAll('.tab-btn');
  const tabContents = container.querySelectorAll('.tab-content');

  let allOrders = [];
  let selectedOrderId = null;
  let selectedValidationId = null;

  // ===== 1. 再描画関数 =====
  function renderOrderList(orders) {
    orderTbody.innerHTML = orders.map(order => {
      const scoreClass = order.信頼度スコア >= 80 ? 'high' : order.信頼度スコア >= 60 ? 'medium' : 'low';
      const scoreColor = order.信頼度スコア >= 80 ? '#44aa44' : order.信頼度スコア >= 60 ? '#ffaa00' : '#ff4444';
      return `
        <tr class="order-row" data-id="${order.id}" data-validation-id="${order.検証結果ID}" style="border-bottom: 1px solid rgba(255,255,255,0.04); cursor: pointer;">
          <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.04);">${order.受注ID || '-'}</td>
          <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.04); color: var(--text-muted);">${order.顧客名 || '-'}</td>
          <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.04); text-align: right; color: var(--text-muted);">¥${(order.受注金額 || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: center; color: ${scoreColor}; font-weight: 600;">${order.信頼度スコア || 0}</td>
        </tr>
      `;
    }).join('');
  }

  function renderIssues(validationResults) {
    issuesList.innerHTML = validationResults.map(v => {
      const severityClass = v.重要度 === '致命的' ? 'high' : v.重要度 === '高' ? 'high' : v.重要度 === '中' ? 'medium' : 'low';
      return `
        <div class="issue-item ${severityClass}">
          <div style="font-weight: 600; color: var(--text); margin-bottom: 2px;">${v.検証項目}</div>
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">${v.エラーメッセージ || v.エラーコード}</div>
          <div style="font-size: 11px; color: var(--text-muted);">
            <span style="display: inline-block; margin-right: 8px;">期待値: ${v.期待値 || '-'}</span>
            <span>実際値: ${v.検証値 || '-'}</span>
          </div>
        </div>
      `;
    }).join('');
    if (validationResults.length === 0) {
      issuesList.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; padding: 8px;">検出された問題はありません</div>';
    }
  }

  function renderMissing(missingResults) {
    missingList.innerHTML = missingResults.map(m => {
      const severityClass = m.重要度 === '高' ? 'high' : m.重要度 === '中' ? 'medium' : 'low';
      return `
        <div class="issue-item ${severityClass}">
          <div style="font-weight: 600; color: var(--text); margin-bottom: 2px;">${m.漏れ項目名}</div>
          <div style="color: var(--text-muted); font-size: 11px;">区分: ${m.漏れ項目区分 || '-'} | ルール: ${m.検出ルール || '-'}</div>
        </div>
      `;
    }).join('');
    if (missingResults.length === 0) {
      missingList.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; padding: 8px;">入力漏れはありません</div>';
    }
  }

  function renderConflicts(conflictResults) {
    conflictsList.innerHTML = conflictResults.map(c => {
      const severityClass = c.重要度 === '高' ? 'high' : c.重要度 === '中' ? 'medium' : 'low';
      return `
        <div class="issue-item ${severityClass}">
          <div style="font-weight: 600; color: var(--text); margin-bottom: 2px;">${c.矛盾タイプ}</div>
          <div style="color: var(--text-muted); font-size: 11px; margin-bottom: 2px;">${c.矛盾内容}</div>
          <div style="font-size: 11px; color: var(--text-muted);">チャネル: ${c.チャネルID_1} ↔ ${c.チャネルID_2}</div>
        </div>
      `;
    }).join('');
    if (conflictResults.length === 0) {
      conflictsList.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; padding: 8px;">チャネル矛盾はありません</div>';
    }
  }

  function showOrderDetail(orderId, validationId) {
    selectedOrderId = orderId;
    selectedValidationId = validationId;

    // 行をハイライト
    container.querySelectorAll('.order-row').forEach(row => row.classList.remove('selected'));
    container.querySelector(`[data-id="${orderId}"]`)?.classList.add('selected');

    // 基本情報を表示
    const order = allOrders.find(o => o.id === orderId);
    if (order) {
      container.querySelector('#detail-order-id').textContent = order.受注ID || '-';
      container.querySelector('#detail-customer').textContent = order.顧客名 || '-';
      container.querySelector('#detail-amount').textContent = `¥${(order.受注金額 || 0).toLocaleString()}`;
      container.querySelector('#detail-channel').textContent = order.チャネル || '-';
      container.querySelector('#detail-date').textContent = order.受注日時 ? new Date(order.受注日時).toLocaleString('ja-JP') : '-';
      container.querySelector('#detail-score').textContent = `${order.信頼度スコア || 0}%`;
    }

    // 検証結果を取得して表示（実装簡略化のため、ここではサンプルデータを使用）
    // 実際には window.aivicApi.list() で各テーブルから該当データを取得する
    const validationResults = tables[0]?.records?.filter(r => r.検証結果ID === validationId) || [];
    const missingResults = tables[1]?.records?.filter(r => r.受注ID === orderId) || [];
    const conflictResults = tables[2]?.records?.filter(r => r.受注ID_1 === orderId || r.受注ID_2 === orderId) || [];

    renderIssues(validationResults);
    renderMissing(missingResults);
    renderConflicts(conflictResults);

    // 承認フォームをリセット
    container.querySelector('#approval-decision').value = '';
    container.querySelector('#approval-priority').value = '';
    container.querySelector('#approval-comment').value = '';
  }

  // ===== 2. 初期データ読み込み =====
  async function loadInitialData() {
    try {
      const orders = await window.aivicApi.list(0); // 受注データ検証結果テーブル
      allOrders = orders || tables[0]?.records || [];
      renderOrderList(allOrders);

      // 最初の受注を自動選択
      if (allOrders.length > 0) {
        showOrderDetail(allOrders[0].id, allOrders[0].検証結果ID);
      }
    } catch (err) {
      console.error('データ読み込みエラー:', err);
      allOrders = tables[0]?.records || [];
      renderOrderList(allOrders);
    }
  }

  loadInitialData();

  // ===== 3. 検索ボタン =====
  container.querySelector('#btn-search').addEventListener('click', () => {
    const orderId = container.querySelector('#search-order-id').value.trim();
    const status = container.querySelector('#filter-status').value;

    let filtered = allOrders;
    if (orderId) {
      filtered = filtered.filter(o => (o.受注ID || '').includes(orderId));
    }
    if (status) {
      filtered = filtered.filter(o => o.検証ステータス === status);
    }

    renderOrderList(filtered);
  });

  // ===== 4. タブ切り替え =====
  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const tabName = btn.dataset.tab;
      tabBtns.forEach(b => b.classList.remove('active'));
      tabContents.forEach(c => c.style.display = 'none');
      btn.classList.add('active');
      container.querySelector(`#tab-${tabName}`).style.display = 'block';
    });
  });

  // ===== 5. 行クリックで詳細表示 =====
  container.addEventListener('click', e => {
    const row = e.target.closest('.order-row');
    if (row) {
      const orderId = row.dataset.id;
      const validationId = row.dataset.validationId;
      showOrderDetail(orderId, validationId);
    }
  });

  // ===== 6. 承認判定を保存 =====
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    if (!selectedOrderId) {
      alert('受注を選択してください');
      return;
    }

    const decision = container.querySelector('#approval-decision').value;
    const priority = container.querySelector('#approval-priority').value;
    const comment = container.querySelector('#approval-comment').value;

    if (!decision) {
      alert('判定結果を選択してください');
      return;
    }

    try {
      // 承認者判定履歴を保存（テーブルインデックスは仮定）
      const result = await window.aivicApi.save(3, {
        受注データID: selectedOrderId,
        連携承認フローID: selectedValidationId,
        承認者ユーザーID: 'current-user-id', // 実装時に現在ユーザーIDを取得
        判定結果: decision,
        判定理由: comment,
        参照検証結果ID: selectedValidationId,
        判定日時: new Date().toISOString()
      });

      if (result) {
        alert(`受注 ${selectedOrderId} を「${decision}」で判定しました`);
        // リストを再読み込み
        loadInitialData();
      }
    } catch (err) {
      console.error('保存エラー:', err);
      alert('判定の保存に失敗しました');
    }
  });

  // ===== 7. キャンセルボタン =====
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#approval-decision').value = '';
    container.querySelector('#approval-priority').value = '';
    container.querySelector('#approval-comment').value = '';
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const validationResultsIdx = 0;
  const correctionHistoryIdx = 1;
  const trustScoreIdx = 2;
  const ocrResultIdx = 3;
  const channelInfoIdx = 4;
  const duplicateDetectionIdx = 5;
  const conflictDetectionIdx = 6;
  const missingDataIdx = 7;
  const approvalFlowIdx = 8;

  let currentOrderId = null;
  let currentValidationResult = null;
