  let trustScores = tables[trustScoreIdx]?.records || [];
  let ocrResults = tables[ocrResultIdx]?.records || [];
  let channelInfo = tables[channelInfoIdx]?.records || [];
  let duplicateDetections = tables[duplicateDetectionIdx]?.records || [];
  let conflictDetections = tables[conflictDetectionIdx]?.records || [];
  let missingDataDetections = tables[missingDataIdx]?.records || [];

