      <div><span style="color: var(--text-muted);">現在値:</span> <strong>${validationResult.検証値 || '(空)'}</strong></div>
      <div><span style="color: var(--text-muted);">期待値:</span> <strong>${validationResult.期待値 || '(指定なし)'}</strong></div>
      <div><span style="color: var(--text-muted);">エラーコード:</span> <strong>${validationResult.エラーコード || '-'}</strong></div>
    `;
  }

  // 修正後フォーム生成
  function renderCorrectionForm(validationResult) {
    const form = container.querySelector("#correction-form");
    if (!validationResult) {
      form.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">エラーを選択してください</div>';
      return;
    }
    form.innerHTML = `
      <div>
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">修正値</label>
        <input type="text" id="correction-value" data-testid="correction-value" value="${validationResult.期待値 || ''}" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.12); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px; box-sizing: border-box;" />
      </div>
      <div>
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">検証ステータス</label>
        <select id="correction-status" data-testid="correction-status" style="width: 100%; padding: 6px 8px; border: 1px solid rgba(255,255,255,0.12); border-radius: 4px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 12px; box-sizing: border-box;">
          <option value="合格">合格</option>
          <option value="警告">警告</option>
          <option value="保留">保留</option>
        </select>
      </div>
    `;
  }

  // 信頼度スコア表示
  function renderTrustScore(orderId) {
    const display = container.querySelector("#trust-score-display");
    const score = trustScores.find(s => s.受注データID === orderId);
    if (!score) {
      display.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">スコアなし</div>';
      return;
    }
    const scoreColor = score.総合スコア >= 80 ? '#4ade80' : score.総合スコア >= 60 ? '#fbbf24' : '#ef4444';
    display.innerHTML = `
      <div style="display: flex; align-items: center; gap: 8px; padding: 8px; background: rgba(0,0,0,0.2); border-radius: 4px;">
        <div style="font-size: 20px; font-weight: 700; color: ${scoreColor};">${score.総合スコア}</div>
        <div style="flex: 1;">
          <div style="font-size: 10px; color: var(--text-muted);">総合スコア</div>
          <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">完全性: ${score.完全性スコア} / 正確性: ${score.正確性スコア} / 一貫性: ${score.一貫性スコア}</div>
        </div>
      </div>
      ${score.警告フラグ ? `<div style="padding: 6px; background: rgba(255, 107, 0, 0.15); border-left: 2px solid #ff6a00; font-size: 10px; color: var(--text); margin-top: 6px;">⚠ 警告: ${score.警告レベル}</div>` : ''}
    `;
  }

  // チャネル情報表示
  function renderChannelInfo(orderId) {
    const display = container.querySelector("#channel-info-display");
    const channel = channelInfo.find(c => c.チャネルID); // 実装簡略化
    if (!channel) {
      display.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">チャネル情報なし</div>';
      return;
    }
    display.innerHTML = `
      <div style="margin-bottom: 4px;"><span style="color: var(--text-muted);">チャネル:</span> ${channel.チャネル名}</div>
      <div style="margin-bottom: 4px;"><span style="color: var(--text-muted);">コード:</span> ${channel.チャネルコード}</div>
      <div style="margin-bottom: 4px;"><span style="color: var(--text-muted);">デフォルト信頼度:</span> ${channel.デフォルト信頼度スコア}</div>
      <div><span style="color: var(--text-muted);">OCR対象:</span> ${channel.OCR処理対象フラグ ? '✓' : '✗'}</div>
    `;
  }

  // OCR結果表示
  function renderOCRResult(orderId) {
    const display = container.querySelector("#ocr-result-display");
    const ocr = ocrResults.find(o => o.order_id === orderId);
    if (!ocr) {
      display.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">OCR結果なし</div>';
      return;
    }
    display.innerHTML = `
      <div style="margin-bottom: 4px;"><span style="color: var(--text-muted);">信頼度:</span> ${ocr.overall_confidence}%</div>
      <div style="margin-bottom: 4px;"><span style="color: var(--text-muted);">ステータス:</span> ${ocr.processing_status}</div>
      <div style="margin-bottom: 4px;"><span style="color: var(--text-muted);">ドキュメント:</span> ${ocr.source_document_type}</div>
      <div><span style="color: var(--text-muted);">手動レビュー:</span> ${ocr.requires_manual_review ? '必要' : '不要'}</div>
    `;
  }

  // 重複検出結果表示
  function renderDuplicateResult(orderId) {
    const display = container.querySelector("#duplicate-result-display");
    const duplicates = duplicateDetections.filter(d => d.主受注ID === orderId || d.副受注ID === orderId);
    if (duplicates.length === 0) {
      display.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">重複なし</div>';
      return;
    }
    display.innerHTML = duplicates.map(d => `
      <div style="padding: 6px; background: rgba(255, 107, 0, 0.1); border-left: 2px solid #ff6a00; margin-bottom: 4px;">
        <div style="font-size: 10px; color: var(--text-muted);">信頼度: ${d.マッチング信頼度}%</div>
        <div style="font-size: 10px; color: var(--text);">${d.マッチング理由}</div>
      </div>
    `).join("");
  }

  // チャネル間矛盾表示
  function renderConflictResult(orderId) {
    const display = container.querySelector("#conflict-result-display");
    const conflicts = conflictDetections.filter(c => c.受注ID_1 === orderId || c.受注ID_2 === orderId);
    if (conflicts.length === 0) {
      display.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">矛盾なし</div>';
      return;
    }
    display.innerHTML = conflicts.map(c => `
      <div style="padding: 6px; background: rgba(255, 193, 7, 0.1); border-left: 2px solid #ffc107; margin-bottom: 4px;">
        <div style="font-size: 10px; color: var(--text-muted);">タイプ: ${c.矛盾タイプ}</div>
        <div style="font-size: 10px; color: var(--text);">重要度: ${c.重要度}</div>
      </div>
    `).join("");
  }

  // 入力漏れ検出表示
  function renderMissingResult(orderId) {
    const display = container.querySelector("#missing-result-display");
    const missing = missingDataDetections.filter(m => m.受注ID === orderId);
    if (missing.length === 0) {
      display.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">漏れなし</div>';
      return;
    }
    display.innerHTML = missing.map(m => `
      <div style="padding: 6px; background: rgba(74, 222, 128, 0.1); border-left: 2px solid #4ade80; margin-bottom: 4px;">
        <div style="font-size: 10px; color: var(--text-muted);">項目: ${m.漏れ項目名}</div>
        <div style="font-size: 10px; color: var(--text);">重要度: ${m.重要度}</div>
      </div>
    `).join("");
  }

  // 初期データ読み込み
  window.aivicApi.list(validationResultsIdx).then(rows => {
    validationResults = rows;
    renderErrorList(validationResults);
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#search-order-id").value;
    const priority = container.querySelector("#filter-priority").value;

    let filtered = validationResults;
    if (orderId) {
      filtered = filtered.filter(r => r.受注データID.includes(orderId));
    }
    if (priority) {
      // 優先度フィルタは修正対象優先度リストと連携（簡略化）
    }

    renderErrorList(filtered);
  });

  // エラー選択
  container.addEventListener("select-error", (e) => {
    const errorId = e.detail.id;
    currentValidationResult = validationResults.find(r => r.検証結果ID === errorId);
    if (currentValidationResult) {
      currentOrderId = currentValidationResult.受注データID;
      renderBeforeData(currentValidationResult);
      renderCorrectionForm(currentValidationResult);
      renderTrustScore(currentOrderId);
      renderChannelInfo(currentOrderId);
      renderOCRResult(currentOrderId);
      renderDuplicateResult(currentOrderId);
      renderConflictResult(currentOrderId);
      renderMissingResult(currentOrderId);
    }
  });

  // 修正を保存
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    if (!currentValidationResult) {
      alert("エラーを選択してください");
      return;
    }

    const correctionValue = container.querySelector("#correction-value").value;
    const correctionStatus = container.querySelector("#correction-status").value;
    const correctionReason = container.querySelector("#correction-reason").value;
    const correctionNote = container.querySelector("#correction-note").value;

    if (!correctionValue || !correctionReason) {
      alert("修正値と修正理由を入力してください");
      return;
    }

    const correctionRecord = {
      修正履歴ID: crypto.randomUUID(),
      受注データID: currentOrderId,
      修正項目名: currentValidationResult.検証項目,
      修正前値: currentValidationResult.検証値,
      修正後値: correctionValue,
      修正理由: correctionReason,
      修正備考: correctionNote,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString(),
      検証結果ID: currentValidationResult.検証結果ID
    };

    const saved = await window.aivicApi.save(correctionHistoryIdx, correctionRecord);
    if (saved) {
      alert("修正を保存しました");
      // 検証結果の対応状況を更新
      await window.aivicApi.update(validationResultsIdx, currentValidationResult.検証結果ID, {
        対応状況: "完了",
        対応者ID: "current-user-id",
        対応完了日時: new Date().toISOString()
      });
      // 画面リセット
      container.querySelector("#correction-value").value = "";
      container.querySelector("#correction-reason").value = "";
      container.querySelector("#correction-note").value = "";
    }
  });

  // 承認フローへ
  container.querySelector("#btn-submit-approval").addEventListener("click", () => {
    if (!currentValidationResult) {
      alert("エラーを選択してください");
      return;
    }
    window.showScreen("scr-1781413369295"); // 連携承認フロー実行画面
  });

  // キャンセル
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    container.querySelector("#correction-value").value = "";
    container.querySelector("#correction-reason").value = "";
    container.querySelector("#correction-note").value = "";
    currentValidationResult = null;
    currentOrderId = null;
    container.querySelector("#before-data-display").innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">エラーを選択してください</div>';
    container.querySelector("#correction-form").innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">エラーを選択してください</div>';
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#order-tbody");
  const filterOrderId = container.querySelector("#filter-order-id");
  const filterDateFrom = container.querySelector("#filter-date-from");
  const filterDateTo = container.querySelector("#filter-date-to");
  const filterStatus = container.querySelector("#filter-status");
  const filterChannel = container.querySelector("#filter-channel");
  const filterScoreMin = container.querySelector("#filter-score-min");
  const filterScoreMax = container.querySelector("#filter-score-max");
  const filterResponse = container.querySelector("#filter-response");
  const btnSearch = container.querySelector("#btn-search");
  const btnReset = container.querySelector("#btn-reset");
  const btnExport = container.querySelector("#btn-export");

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusColor = {
        '合格': '#4ade80',
        '不合格': '#ef4444',
        '警告': '#f59e0b',
        '保留': '#6b7280'
      }[r.検証ステータス] || '#9ca3af';

      const responseColor = {
        '完了': '#4ade80',
        '対応中': '#3b82f6',
        '未対応': '#ef4444',
        '却下': '#6b7280'
      }[r.対応状況] || '#9ca3af';

      const score = parseInt(r.信頼度スコア) || 0;
      const scoreColor = score >= 80 ? '#4ade80' : score >= 60 ? '#f59e0b' : '#ef4444';

      return `
        <tr data-id="${r.受注ID}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background='transparent'">
          <td style="padding: 10px 12px; color: var(--text); font-family: monospace; font-size: 12px;">${r.受注ID || ''}</td>
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${r.受注日時 ? new Date(r.受注日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : ''}</td>
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${r.チャネル || ''}</td>
          <td style="padding: 10px 12px;">
            <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; background: ${statusColor}; color: #fff; font-size: 11px; font-weight: 500;">${r.検証ステータス || ''}</span>
          </td>
          <td style="padding: 10px 12px; text-align: center;">
            <div style="display: flex; align-items: center; justify-content: center; gap: 6px;">
              <div style="width: 60px; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
                <div style="width: ${score}%; height: 100%; background: ${scoreColor}; transition: width 0.3s;"></div>
              </div>
              <span style="color: var(--text); font-size: 11px; font-weight: 500; min-width: 30px;">${score}</span>
            </div>
          </td>
          <td style="padding: 10px 12px;">
            <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; background: ${responseColor}; color: #fff; font-size: 11px; font-weight: 500;">${r.対応状況 || ''}</span>
          </td>
          <td style="padding: 10px 12px; color: var(--text-muted); font-size: 12px; max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.検証結果 || ''}">${r.検証結果 || '—'}</td>
          <td style="padding: 10px 12px; text-align: center;">
            <button class="detail-btn" data-id="${r.受注ID}" style="background: transparent; color: var(--primary); border: none; font-size: 12px; cursor: pointer; text-decoration: underline; padding: 2px 4px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 2. 初期データ描画
  renderRows(tables[0].records || []);

  // 3. 検索ボタン
  btnSearch.addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const orderId = (r.受注ID || '').toLowerCase();
      const keyword = filterOrderId.value.toLowerCase();
      if (keyword && !orderId.includes(keyword)) return false;

      const dateFrom = filterDateFrom.value ? new Date(filterDateFrom.value) : null;
      const dateTo = filterDateTo.value ? new Date(filterDateTo.value + 'T23:59:59') : null;
      const orderDate = r.受注日時 ? new Date(r.受注日時) : null;
      if (dateFrom && orderDate && orderDate < dateFrom) return false;
      if (dateTo && orderDate && orderDate > dateTo) return false;

      if (filterStatus.value && r.検証ステータス !== filterStatus.value) return false;
      if (filterChannel.value && r.チャネル !== filterChannel.value) return false;

      const scoreMin = filterScoreMin.value ? parseInt(filterScoreMin.value) : 0;
      const scoreMax = filterScoreMax.value ? parseInt(filterScoreMax.value) : 100;
      const score = parseInt(r.信頼度スコア) || 0;
      if (score < scoreMin || score > scoreMax) return false;

      if (filterResponse.value && r.対応状況 !== filterResponse.value) return false;

      return true;
    });

    renderRows(filtered);
  });

  // 4. リセットボタン
  btnReset.addEventListener("click", () => {
    filterOrderId.value = '';
    filterDateFrom.value = '';
    filterDateTo.value = '';
    filterStatus.value = '';
    filterChannel.value = '';
    filterScoreMin.value = '';
    filterScoreMax.value = '';
    filterResponse.value = '';
    renderRows(tables[0].records || []);
  });

  // 5. CSVエクスポート
  btnExport.addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const columns = ['受注ID', '受注日時', 'チャネル', '検証ステータス', '信頼度スコア', '対応状況', '検証結果'];
    const csvContent = [
      '\uFEFF' + columns.join(','),
      ...rows.map(r => columns.map(col => {
        const val = r[col] || '';
        const str = String(val).replace(/"/g, '""');
        return str.includes(',') || str.includes('"') || str.includes('\n') ? `"${str}"` : str;
      }).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `order_status_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 6. 詳細ボタン（行クリック）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const orderId = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852", { orderId });
    }
  });
}

function(container, apiUrl, tables) {
  const scoreListTbody = container.querySelector("#score-list-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const noSelectionPanel = container.querySelector("#no-selection-panel");

  let allRows = [];
  let selectedRowId = null;

  // 1. 再描画関数
  function renderRows(rows) {
    allRows = rows;
    scoreListTbody.innerHTML = rows.map(r => {
      const score = r.総合スコア || 0;
      const priority = r.優先度レベル || 5;
      const warningFlag = r.警告フラグ || false;
      const warningLevel = r.警告レベル || "-";

      let scoreColor = "#4ade80"; // 高
      if (score < 31) scoreColor = "#ef4444"; // 低
      else if (score < 61) scoreColor = "#f59e0b"; // 中

      return `
        <tr 
          data-id="${r.信頼度スコアID || ''}" 
          class="score-row" 
          style="background: var(--bg-main); border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;"
        >
          <td style="padding: 8px; color: var(--text); font-size: 12px; word-break: break-all;">
            ${r.受注データID ? r.受注データID.substring(0, 8) + '...' : '-'}
          </td>
          <td style="padding: 8px; text-align: center; color: ${scoreColor}; font-weight: 700; font-size: 13px;">
            ${score}
          </td>
          <td style="padding: 8px; text-align: center;">
            ${warningFlag ? `<span style="background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600;">${warningLevel}</span>` : '<span style="color: var(--text-muted); font-size: 11px;">-</span>'}
          </td>
          <td style="padding: 8px; text-align: center; color: var(--text); font-size: 12px;">
            ${priority}
          </td>
        </tr>
      `;
    }).join("");

    // イベントデリゲーション: 行クリック
    container.querySelectorAll(".score-row").forEach(row => {
      row.addEventListener("click", () => {
        const id = row.dataset.id;
        selectRow(id);
      });
    });
  }

  // 2. 行選択時の詳細表示
  function selectRow(id) {
    selectedRowId = id;
    const row = allRows.find(r => r.信頼度スコアID === id);
    if (!row) return;

    // パネル表示切り替え
    detailPanel.style.display = "block";
    noSelectionPanel.style.display = "none";

    // 詳細情報を埋める
    container.querySelector("#detail-overall-score").textContent = row.総合スコア || 0;
    container.querySelector("#detail-warning-level").textContent = row.警告レベル || "-";
    container.querySelector("#detail-completeness").textContent = row.完全性スコア || 0;
    container.querySelector("#detail-accuracy").textContent = row.正確性スコア || 0;
    container.querySelector("#detail-consistency").textContent = row.一貫性スコア || 0;
    container.querySelector("#detail-requires-fix").checked = row.警告フラグ || false;

    // 修正前値（ダミー）
    container.querySelector("#detail-before-value").textContent = row.備考 || "（OCR読み込み結果）";
    container.querySelector("#compare-before").textContent = row.備考 || "-";
    container.querySelector("#compare-after").textContent = "-";

    // 修正フォームをリセット
    container.querySelector("#detail-fix-field").value = "";
    container.querySelector("#detail-after-value").value = "";
    container.querySelector("#detail-fix-reason").value = "";
    container.querySelector("#detail-fix-comment").value = "";
  }

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#search-order-id").value.trim();
    const scoreRange = container.querySelector("#filter-score-range").value;
    const priority = container.querySelector("#filter-priority").value;

    let filtered = allRows;

    if (orderId) {
      filtered = filtered.filter(r => 
        (r.受注データID || "").includes(orderId)
      );
    }

    if (scoreRange) {
      const [min, max] = scoreRange.split("-").map(Number);
      filtered = filtered.filter(r => {
        const score = r.総合スコア || 0;
        return score >= min && score <= max;
      });
    }

    if (priority) {
      filtered = filtered.filter(r => r.優先度レベル === parseInt(priority));
    }

    renderRows(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#search-order-id").value = "";
    container.querySelector("#filter-score-range").value = "";
    container.querySelector("#filter-priority").value = "";
    renderRows(allRows);
  });

  // 5. 修正後値入力時に比較を更新
  container.querySelector("#detail-after-value").addEventListener("input", (e) => {
    const afterValue = e.target.value;
    container.querySelector("#compare-after").textContent = afterValue || "-";
  });

  // 6. 修正を保存ボタン
  container.querySelector("#btn-save-fix").addEventListener("click", async () => {
    if (!selectedRowId) {
      alert("修正対象を選択してください");
      return;
    }

    const fixField = container.querySelector("#detail-fix-field").value;
    const afterValue = container.querySelector("#detail-after-value").value;
    const fixReason = container.querySelector("#detail-fix-reason").value;
    const fixComment = container.querySelector("#detail-fix-comment").value;

    if (!fixField || !afterValue || !fixReason) {
      alert("修正項目、修正後値、修正理由を入力してください");
      return;
    }

    // 修正履歴を保存（テーブルインデックス 1 = 受注データ修正履歴）
    const beforeRow = allRows.find(r => r.信頼度スコアID === selectedRowId);
    const beforeValue = beforeRow?.備考 || "";

    const saved = await window.aivicApi.save(1, {
      受注データID: beforeRow?.受注データID || "",
      修正項目名: fixField,
      修正前値: beforeValue,
      修正後値: afterValue,
      修正理由: fixReason,
      修正備考: fixComment,
      修正ユーザーID: "current-user",
      修正日時: new Date().toISOString()
    });

    if (saved) {
      alert("修正を保存しました");
      // 信頼度スコアを更新（テーブルインデックス 2 = 信頼度スコア）
      await window.aivicApi.update(2, selectedRowId, {
        警告フラグ: false,
        警告レベル: "解決済み"
      });
      // 一覧を再読み込み
      const updated = await window.aivicApi.list(2);
      renderRows(updated || allRows);
      detailPanel.style.display = "none";
      noSelectionPanel.style.display = "flex";
      selectedRowId = null;
    }
  });

  // 7. キャンセルボタン
  container.querySelector("#btn-cancel-fix").addEventListener("click", () => {
    detailPanel.style.display = "none";
    noSelectionPanel.style.display = "flex";
    selectedRowId = null;
  });

  // 8. 初期データ読み込み（テーブルインデックス 2 = 信頼度スコア）
  window.aivicApi.list(2).then(rows => {
    if (rows && rows.length > 0) {
      renderRows(rows);
    } else if (tables[2] && tables[2].records) {
      renderRows(tables[2].records);
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const DUPLICATE_RESULTS_IDX = 0;
  const VALIDATION_RESULTS_IDX = 1;
  const CONFIDENCE_SCORES_IDX = 2;
  const CHANNEL_CONFLICTS_IDX = 3;
  const APPROVAL_FLOW_IDX = 4;
  const APPROVAL_HISTORY_IDX = 5;

  let duplicateGroups = [];
  let selectedGroupId = null;
  let selectedMasterOrderId = null;
  let selectedMergeTargets = [];

  // 1. 重複グループ一覧を取得・描画
  async function loadDuplicateGroups() {
    const results = await window.aivicApi.list(DUPLICATE_RESULTS_IDX) || tables[DUPLICATE_RESULTS_IDX]?.records || [];

    // グループ化: 主受注IDごとにグループ化
    const groupMap = {};
    results.forEach(r => {
      if (!groupMap[r.主受注ID]) {
        groupMap[r.主受注ID] = {
          groupId: r.主受注ID,
          masterOrderId: r.主受注ID,
          duplicates: [],
          matchingConfidence: r.マッチング信頼度 || 0,
          status: r.検出ステータス || '未確認'
        };
      }
      groupMap[r.主受注ID].duplicates.push({
        orderId: r.副受注ID,
        confidence: r.マッチング信頼度,
        reason: r.マッチング理由
      });
    });

    duplicateGroups = Object.values(groupMap);
    renderGroupList();
  }

  // グループリスト描画
  function renderGroupList() {
    const groupList = container.querySelector('#group-list');
    groupList.innerHTML = duplicateGroups.map(g => `
      <div 
        class="group-item" 
        data-group-id="${g.groupId}" 
        style="padding: 8px; margin-bottom: 4px; background: ${selectedGroupId === g.groupId ? 'var(--primary)' : 'var(--bg-card)'}; border-radius: 4px; cursor: pointer; border-left: 3px solid #ff6a00; transition: all 0.2s;"
      >
        <div style="font-size: 11px; font-weight: 600; color: ${selectedGroupId === g.groupId ? '#fff' : 'var(--text)'};">
          グループ #${g.groupId.substring(0, 8)}
        </div>
        <div style="font-size: 10px; color: ${selectedGroupId === g.groupId ? 'rgba(255,255,255,0.8)' : 'var(--text-muted)'}; margin-top: 2px;">
          重複件数: ${g.duplicates.length + 1}
        </div>
        <div style="font-size: 10px; color: ${selectedGroupId === g.groupId ? 'rgba(255,255,255,0.8)' : 'var(--text-muted)'};">
          信頼度: ${g.matchingConfidence}%
        </div>
      </div>
    `).join('');

    // グループクリックイベント
    container.querySelectorAll('.group-item').forEach(el => {
      el.addEventListener('click', () => {
        selectedGroupId = el.dataset.groupId;
        selectedMasterOrderId = null;
        selectedMergeTargets = [];
        renderGroupList();
        renderComparisonTable();
        updateMergeForm();
      });
    });
  }

  // 2. 受注比較テーブル描画
  async function renderComparisonTable() {
    if (!selectedGroupId) {
      container.querySelector('#comparison-tbody').innerHTML = '<tr><td colspan="4" style="padding: 16px; text-align: center; color: var(--text-muted);">グループを選択してください</td></tr>';
      return;
    }

    const group = duplicateGroups.find(g => g.groupId === selectedGroupId);
    if (!group) return;

    // マスター受注と副受注を取得（実装では仮データを使用）
    const allOrders = [
      { id: group.masterOrderId, 顧客名: '顧客A', 受注金額: '100,000', 受注日: '2025-01-15', チャネル: 'Web', 信頼度: 95 },
      ...group.duplicates.map((d, i) => ({
        id: d.orderId,
        顧客名: '顧客A',
        受注金額: '100,000',
        受注日: '2025-01-15',
        チャネル: i % 2 === 0 ? '電話' : 'API',
        信頼度: d.confidence
      }))
    ];

    const tbody = container.querySelector('#comparison-tbody');
    const items = ['顧客名', '受注金額', '受注日', 'チャネル'];

    tbody.innerHTML = items.map(item => {
      const row = allOrders.map(o => o[item] || '-').join(' | ');
      return `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 8px; color: var(--text-muted); font-weight: 600; border-right: 1px solid var(--border);">${item}</td>
          ${allOrders.map((o, idx) => {
            const val = o[item] || '-';
            const isMismatch = idx > 0 && o[item] !== allOrders[0][item];
            return `<td style="padding: 8px; color: ${isMismatch ? '#ff6a00' : 'var(--text)'}; border-right: 1px solid var(--border); background: ${isMismatch ? 'rgba(255, 106, 0, 0.1)' : 'transparent'};">${val}</td>`;
          }).join('')}
          <td style="padding: 8px; color: var(--text);">${allOrders[0].信頼度}%</td>
        </tr>
      `;
    }).join('');

    // チャネル矛盾検出結果
    const conflictResults = await window.aivicApi.list(CHANNEL_CONFLICTS_IDX) || tables[CHANNEL_CONFLICTS_IDX]?.records || [];
    const relevantConflicts = conflictResults.filter(c => 
      (c.受注ID_1 === group.masterOrderId || c.受注ID_2 === group.masterOrderId) ||
      group.duplicates.some(d => c.受注ID_1 === d.orderId || c.受注ID_2 === d.orderId)
    );

    const conflictDiv = container.querySelector('#channel-conflicts');
    conflictDiv.innerHTML = relevantConflicts.length > 0 
      ? relevantConflicts.map(c => `
          <div style="padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.1);">
            <strong style="color: #ff6a00;">${c.矛盾タイプ}</strong>: ${c.矛盾内容}
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">重要度: ${c.重要度}</div>
          </div>
        `).join('')
      : '<div style="color: var(--text-muted);">矛盾なし</div>';
  }

  // 3. マージフォーム更新
  async function updateMergeForm() {
    if (!selectedGroupId) return;

    const group = duplicateGroups.find(g => g.groupId === selectedGroupId);
    if (!group) return;

    // マスター受注セレクト
    const masterSelect = container.querySelector('#master-order-select');
    const allOrderIds = [group.masterOrderId, ...group.duplicates.map(d => d.orderId)];
    masterSelect.innerHTML = '<option value="">選択してください</option>' + allOrderIds.map(id => 
      `<option value="${id}" ${selectedMasterOrderId === id ? 'selected' : ''}>受注 ${id.substring(0, 8)}</option>`
    ).join('');

    masterSelect.addEventListener('change', (e) => {
      selectedMasterOrderId = e.target.value;
      updateMergePreview();
    });

    // マージ対象チェックボックス
    const mergeTargetsDiv = container.querySelector('#merge-targets');
    mergeTargetsDiv.innerHTML = group.duplicates.map(d => `
      <label style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px; cursor: pointer;">
        <input 
          type="checkbox" 
          class="merge-target-checkbox" 
          value="${d.orderId}"
          style="accent-color: var(--primary);"
        />
        <span>受注 ${d.orderId.substring(0, 8)} (信頼度: ${d.confidence}%)</span>
      </label>
    `).join('');

    container.querySelectorAll('.merge-target-checkbox').forEach(cb => {
      cb.addEventListener('change', (e) => {
        if (e.target.checked) {
          selectedMergeTargets.push(e.target.value);
        } else {
          selectedMergeTargets = selectedMergeTargets.filter(id => id !== e.target.value);
        }
        updateMergePreview();
      });
    });

    // 信頼度スコア比較
    const scoreDiv = container.querySelector('#score-comparison');
    const scores = await window.aivicApi.list(CONFIDENCE_SCORES_IDX) || tables[CONFIDENCE_SCORES_IDX]?.records || [];
    const relevantScores = scores.filter(s => allOrderIds.includes(s.受注データID));

    scoreDiv.innerHTML = relevantScores.map(s => `
      <div style="display: flex; justify-content: space-between; margin-bottom: 2px;">
        <span>受注 ${s.受注データID.substring(0, 8)}</span>
        <span style="color: ${s.総合スコア >= 80 ? '#4caf50' : s.総合スコア >= 60 ? '#ff9800' : '#f44336'}; font-weight: 600;">${s.総合スコア}%</span>
      </div>
    `).join('');
  }

  // 4. マージプレビュー更新
  function updateMergePreview() {
    const previewDiv = container.querySelector('#merge-preview');

    if (!selectedMasterOrderId || selectedMergeTargets.length === 0) {
      previewDiv.innerHTML = '<div style="color: var(--text-muted);">マスター受注とマージ対象を選択してください</div>';
      return;
    }

    previewDiv.innerHTML = `
      <div style="margin-bottom: 4px;"><strong>マスター:</strong> 受注 ${selectedMasterOrderId.substring(0, 8)}</div>
      <div><strong>マージ対象:</strong></div>
      ${selectedMergeTargets.map(id => `<div style="margin-left: 8px;">• 受注 ${id.substring(0, 8)}</div>`).join('')}
      <div style="margin-top: 6px; padding-top: 6px; border-top: 1px solid rgba(255,255,255,0.1); color: #4caf50; font-weight: 600;">
        ✓ マージ準備完了
      </div>
    `;
  }

  // 5. マージ実行
  container.querySelector('#btn-merge').addEventListener('click', () => {
    if (!selectedMasterOrderId || selectedMergeTargets.length === 0) {
      alert('マスター受注とマージ対象を選択してください');
      return;
    }

    const dialog = container.querySelector('#merge-confirm-dialog');
    const message = container.querySelector('#confirm-message');
    message.innerHTML = `
      <div>マスター受注: <strong>${selectedMasterOrderId.substring(0, 8)}</strong></div>
      <div style="margin-top: 6px;">マージ対象: <strong>${selectedMergeTargets.length}</strong> 件</div>
      <div style="margin-top: 6px; color: #ff6a00;">この操作は取り消せません。よろしいですか？</div>
    `;
    dialog.removeAttribute('hidden');
  });

  // 6. マージ確認ダイアログ
  container.querySelector('#btn-confirm-merge').addEventListener('click', async () => {
    const dialog = container.querySelector('#merge-confirm-dialog');
    dialog.setAttribute('hidden', '');

    // マージ処理実行（API呼び出し）
    const mergePayload = {
      masterOrderId: selectedMasterOrderId,
      mergeTargetIds: selectedMergeTargets,
      mergedAt: new Date().toISOString(),
      status: '統合済み'
    };

    const result = await window.aivicApi.save(DUPLICATE_RESULTS_IDX, mergePayload);
    if (result) {
      alert('マージ処理が完了しました');
      selectedGroupId = null;
      selectedMasterOrderId = null;
      selectedMergeTargets = [];
      await loadDuplicateGroups();
      renderComparisonTable();
      updateMergeForm();
      loadApprovalTimeline();
    }
  });

  container.querySelector('#btn-confirm-cancel').addEventListener('click', () => {
    container.querySelector('#merge-confirm-dialog').setAttribute('hidden', '');
  });

  container.querySelector('#btn-cancel-merge').addEventListener('click', () => {
    selectedMasterOrderId = null;
    selectedMergeTargets = [];
    updateMergeForm();
  });

  // 7. グループ検索
  container.querySelector('#group-search').addEventListener('input', (e) => {
    const kw = e.target.value.toLowerCase();
    container.querySelectorAll('.group-item').forEach(el => {
      const text = el.textContent.toLowerCase();
      el.style.display = text.includes(kw) ? 'block' : 'none';
    });
  });

  // 8. 承認者判定履歴タイムライン
  async function loadApprovalTimeline() {
    const history = await window.aivicApi.list(APPROVAL_HISTORY_IDX) || tables[APPROVAL_HISTORY_IDX]?.records || [];
    const timeline = container.querySelector('#approval-timeline');

    if (history.length === 0) {
      timeline.innerHTML = '<div style="color: var(--text-muted);">承認履歴なし</div>';
      return;
    }

    timeline.innerHTML = history.slice(0, 5).map(h => `
      <div style="padding: 6px 0; border-left: 2px solid #ff6a00; padding-left: 8px; margin-bottom: 6px;">
        <div style="font-weight: 600; color: var(--text);">${h.判定結果}</div>
        <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${h.判定理由}</div>
        <div style="font-size: 10px; color: var(--text-muted);">判定日: ${new Date(h.判定日時).toLocaleString('ja-JP')}</div>
      </div>
    `).join('');
  }

  // 初期化
  loadDuplicateGroups();
  loadApprovalTimeline();
}
